(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["4-3"] = [{"a": [84], "v": 3, "p": 1355, "ev": 3, "ep": 1358, "sid": 1556, "t": "قوله عز وجل: (فقاتل في سبيل الله لا تكلف إلا نفسك وحرض المؤمنين عسى الله أن يكف بأس الذين كفروا والله أشد بأسا وأشد تنكيلا (84)\n⟦3:1356⟧\nالتنكيل: مصدر نكلت به، والنكال العقوبة التي تنكل المعاقب\nوغير المعاقب عن إتيان مثله، وأصله من النكل، وهو ضرب من\nالقيد، ومنه نكل عن الشيء .\nإن قيل: كيف قال: ﴿لَا تُكَلَّفُ إِلَّا نَفۡسَكَۚ﴾⟪4:84⟫ وقد بعث النبي - صلى الله عليه وسلم - ليكلف الناس؟\nقيل: لم يعن التكليف الاستدعاء الذي رشح له، ألا ترى أنه قال ﴿وَحَرِّضِ ٱلۡمُؤۡمِنِينَۖ﴾⟪4:84⟫ الآية تقتضي أن على الإنسان أن لا يني في نصرة الحق وإن تفرد، يعد أن لا يني في فعله.\nوروي أن أبا بكر رضي الله عنه قال: \"لو خالفتني يميني جاهدتها بشمالي\" وتلا هذه الآية.\nوقال بعض الحكماء: من\n⟦3:1357⟧\nطلب رفيقا في سلوك طريق الحق فلقلة يقينه، وسوء معرفته.\nفالمحقق للسعادة والعارف بالطريق إليها لا يفرح على رفيق ولا\nيبالي بطول طريق، فمن خطب الحسناء لم يغلها مهر.\nوالفاء في قوله: (فقاتل) قال الزجاج: هو جواب لقوله: ﴿وَمَن يَقۡتُلۡ﴾، ووجه ذلك أنه محمول على المعنى كأنه قال: إن\nأردت الفوز بذلك فقاتل، وقال بعضهم: هو متصل بقوله:\n﴿وَمَا لَكُمۡ لَا تُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِ﴾⟪4:75⟫.\nوقوله: ﴿عَسَى ٱللَّهُ أَن يَكُفَّ بَأۡسَ ٱلَّذِينَ كَفَرُواْۚ﴾⟪4:84⟫\nأي كن راجيا في دفع أذاهم،\n⟦3:1358⟧\nوقول المفسرين: عسى من الله واجب، أي الكريم إذا رجي\nحقق، وقوله: ﴿وَٱللَّهُ أَشَدُّ بَأۡسٗا وَأَشَدُّ تَنكِيلٗا﴾⟪4:84⟫\nتنبيه أنك لا تحتاج أن تقصر عن قتالهم، فالله معك، وهو أشد بأسا\nمن عداك، فلا يجب أن ينكادك من تاخر عنك."}, {"a": [85], "v": 3, "p": 1358, "ev": 3, "ep": 1366, "sid": 1559, "t": "قوله عز وجل: (من يشفع شفاعة حسنة يكن له نصيب منها ومن يشفع شفاعة سيئة يكن له كفل منها وكان الله على كل شيء مقيتا (85)\nالشفاعة: من الشفع أي ضم الشيء إلى غيره.\nوضد قولهم شفعه: أفرده، ولهذا قال الشاعر:\nومن يفرد الإخوان فيما ينوبهم. . . تصبه الليالي مرة وهو مفرد\n⟦3:1359⟧\nوالشفعة متعارفة في ضم ملك بيع إلى ملكك، والشفاعة في\nانضمام إنسان إلى آخر فيما يطلبه، والشفاعة المذكورة.\nفي نحو قوله: ﴿وَلَا يُقۡبَلُ مِنۡهَا شَفَٰعَةٞ﴾⟪2:48⟫ هي في الآخرة معروفة\nوأما في الدنيا فبأن يهدي الإنسان غيره، فمن هدى غيره إلى\nطريق خير فقد شفع له.\nوأصل الكفل الكفل، فجعل اسما لمركب من خرق\nوكساء يوضع على الكفل، وقد يسمى ما يكسى العضو\nباسمه، كقولهم: يد القميص وبدنه، ورجل السراويل، والساق\nوالساعد لما يلبس هذين العضوين، ثم استعير الكفل تارة\n⟦3:1360⟧\nإن نبا ركوبه تشبيها بذلك المركب. قال الشاعر:\nغير ميل ولاعواوين في الهي. . . جا ولا عزل ولا أكفال\nثم سمي الفاجر في أي أمر كان كفلا، ولما كان ذلك الكفل\nيجعل على قدر الكفل تصور فيه المماثلة، فقيل للمثل في العدد كفل.\nفإن قيل: فلم فرق بينهما فقال في الحسنة: (نصيب)، وفي السيئة (كفل)؟\nقيل: يجوز أنه لما كان النصيب يقال فيما\n⟦3:1361⟧\nيقل ويكثر، والكفل لا يقال إلا في المثل جاء في السيئة بلفظ\nالكفل تنبيها على معنى المماثلة، وإشارة إلى ما قال: ﴿وَمَن جَآءَ بِٱلسَّيِّئَةِ فَلَا يُجۡزَىٰٓ إِلَّا مِثۡلَهَا﴾⟪6:160⟫.\nوقد قيل: الكفل المذكور هاهنا أكثر ما يقال في الشيء الرديء، فنبه بلفظه على ذلك تنبيها على قوله: ﴿وَجَزَٰٓؤُاْ سَيِّئَةٖ سَيِّئَةٞ مِّثۡلُهَاۖ﴾⟪42:40⟫.\nفإن قيل: فقد قال ﴿يُؤۡتِكُمۡ كِفۡلَيۡنِ مِن رَّحۡمَتِهِۦ﴾⟪57:28⟫، وليس ذلك بمذموم؟\nقيل: إنه عنى بالكفلين هاهنا أي له كفيلان من رحمته يتكفلان به من العذاب،\n⟦3:1362⟧\nفيضارع اللفظان، والمعنيان مختلفان، ولما حث الله تعالى في الآية\nالمتقدمة على تكلف ما أمر وتحريض المؤمنين، ورجاء الظفر\nبالكفار، بين هاهنا أن من أعان غيره في فعل حسن فله نصيب في\nثوابه، وإن أعانه في فعل سيئ فله كفل منه، وذلك عبارة عما\nبينه النبي - صلى الله عليه وسلم - بقوله:\n\"من سن سنة حسنة فله أجرها وأجر من عمل بها\" الخبر.\nوقال بعضهم: القصد بذلك أن من يدعو لغيره دعاء حسنا\nفله فيه نصيب، ومن فعل بخلاف ذلك فكذلك.\nقال: والسبب في هذا أن اليهود والمنافقين كانوا إذا دخلوا\nعلى النبي - صلى الله عليه وسلم - يقولون: السام عليكم، يوهمون أنهم يقولون:\n⟦3:1363⟧\nالسلام عليكم، فأنزل الله ذلك، واستدل قائل هذا بقوله تعالى\nبعد ذلك: ﴿وَإِذَا حُيِّيتُم بِتَحِيَّةٖ فَحَيُّواْ بِأَحۡسَنَ مِنۡهَآ أَوۡ رُدُّوهَآۗ﴾⟪4:86⟫.\nوقوله: ﴿وَكَانَ ٱللَّهُ عَلَىٰ كُلِّ شَيۡءٖ مُّقِيتٗا﴾⟪4:85⟫\nقال السدي: المقيت: المقتدر، وأنشد الكسائي فيه:\n⟦3:1364⟧\n. . . . . . . . . . . . . . . . . . . . . . وكنت على مساءته مقيتا\nوقال ابن عباس: الحفيظ، وقواه الرجاج .\nوقال مجاهد: الشهيد، وروي عنه: الحسيب،\n⟦3:1365⟧\nوقال الضحاك: الرازق.\nوقال غيرهم: المجازي، وحقيقته الذي يجعل للإنسان قوتا.\nوفي الحديث: \"كفى بالمرء إثما أن يضيع من يقوت \"\n- ويقيت - كأن الله تعالى يجعل لكل إنسان قوتا من\nالجزاء بقدر فعله، ويجعل له في الدنيا والآخرة قدر ما يستوجبه.\nوما قالوه فصحيح من حيث المقصد، لأن ما قدره الله\nتعالى للعبد فقد حفظه وشهده.\nوروي أن رجلا سأل عبد الله بن رواحة عن المقيت؟\nفقال: يقيت كل إنسان بقدر علمه.\n⟦3:1366⟧\nكأنه إشارة إلى ما قال عليه الصلاة والسلام:\n\"إن الله يحاسب عباده بقدر عقولهم \"."}, {"a": [86], "v": 3, "p": 1366, "ev": 3, "ep": 1372, "sid": 1567, "t": "قوله عز وجل: (وإذا حييتم بتحية فحيوا بأحسن منها أو ردوها إن الله كان على كل شيء حسيبا (86)\nالتحية: من قولهم حيا الله فلانا، أي جعل له حياة، وذلك\nإخبار، ثم يجعل دعاء، ثم يقال: وحيا فلان فلانا إذا قال له\nذلك، وحكم به، كما يقال: أضللت فلانا وأرشدته إذا\nحكمت له بذلك، وأصل التحية من الحياة، ثم يقال لكل دعاء\nتحية، لكون جميعه غير خارج عن كونه حياة، أو سبب حياة.\nإما دنيوية وإما أخروية.\nإن قيل: علي أي وجه\n⟦3:1367⟧\nجعل قولهم: السلام تحية الملتقين؟\nقيل: السلام والسلم واحد، بدلالة قوله: ﴿فَقَالُواْ سَلَٰمٗاۖ قَالَ سَلَٰمٞ﴾⟪51:25⟫ (1)\nولما كان الملتقيان من الأجانب قد حذر أحدهما الآخر استعملوا هذه\nاللفظة تنبيها من المخاطب، أي بذلت لك ذلك وطلبته منك.\nونبه المجيب إذا قال: وعليك السلام. على نحو ذلك، ثم صار\nذلك مستعملا في الأجانب والأقارب والأعادي والأحباب، تنبيها\nأني أسأل الله ذلك لك، وأكثر المفسرين حملوا الآية على التحية\nالمجردة، فقالوا معناه: من حياكم بتحية فحيوا بأحسن منها أو\nردوها أي قابلوه بمثلها، قالوا: ورد ذلك أنه متى قال قائل:\nالسلام عليكم، فإنه يقول: وعليكم السلام، أو يقول:\nوعليكم، فهذا هو رده، ويدل أنه إذا قال: وعليكم. فقد رد، أن\nرجلا دخل على عمر فقال: السلام عليكم ورحمة الله\nوبركاته، فقال عمر: وعليكم، فظن الرجل أنه لم يسمع عمر.\n⟦3:1368⟧\nفأعاد عليه ، فأعاد عمر مثل ما قال، فقال الرجل: يا أمير المؤمنين\nألا ترد علي كما أقول؟\nقال: أو لم أفعل؟ وأما أحسن منها فأن يقول له أكثر من ذلك ما لم يستوف المسلم ألفاظ التحية، وذلك أن رجلا أتى النبي - صلى الله عليه وسلم - فقال: السلام عليكم فقال النبي - صلى الله عليه وسلم -:\n\"عليكم السلام ورحمة الله \".\nثم أتى آخر فقال: السلام عليكم ورحمة الله، فقال - صلى الله عليه وسلم -: \"وعليكم السلام ورحمة الله وبركاته \".\nفجاء ثالث فقال: السلام عليكم ورحمة الله وبركاته.\nفقال - صلى الله عليه وسلم -: \"وعليكم \".\nفقيل له في ذلك، فقال: \"إن الأول والثاني أتيا من التحية شيئا فرددت عليهما بأحسن مما سلما، والثالث حياني بالتحية كلها فرددت عليه مثلها\".\nومن المفسرين من قال له: إن من حياكم ببعض التحية\n⟦3:1369⟧\nفحيوا بها تامة، ومن حياكم بالتحية تامة فردوا مثلها، ومنهم\nمن قال: بل خير كلهم بين الأمرين، وقال قتادة: بأحسن منها\nللمسلمين، وبمثلها أهل الكتاب، وهو أن يقال: وعليكم.\nوقال ابن عباس: من سلم عليك من خلق الله فاردد عليه، وإن\nكان مجوسيا.\nومن المفسرين من حمل ذلك على الهدايا واللطف،\n⟦3:1370⟧\nوقال: حق من تولى شيئا أن يولي مثله وأحسن منه.\nومنهم من قال: السلام هاهنا السلم، وهو أصله، قال: وهذا أمر منه\nأن من بذل لكم السلم من الكفار بأن يروم الدخول في الشرع.\nفابذلوا له، كقوله: ﴿وَإِن جَنَحُواْ لِلسَّلۡمِ فَٱجۡنَحۡ لَهَا﴾⟪8:61⟫.\nقال: وأمر بأن يرد على باذلها مثلها أو أكثر منها.\nقال: ومثله أن يبذل له الأمان مما خافه، وأكثر منه أن يبين أن له ما لهم، وعليه ما عليهم من النصرة والموالاة، وذلك مما قد بينه في قوله: ﴿وَٱلۡمُؤۡمِنُونَ وَٱلۡمُؤۡمِنَٰتُ بَعۡضُهُمۡ أَوۡلِيَآءُ بَعۡضٖۚ﴾⟪9:71⟫.\nقال: وذلك هو الذي بسطه من بعد في قوله: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓاْ إِذَا ضَرَبۡتُمۡ فِي سَبِيلِ ٱللَّهِ فَتَبَيَّنُواْ وَلَا تَقُولُواْ لِمَنۡ أَلۡقَىٰٓ إِلَيۡكُمُ ٱلسَّلَٰمَ لَسۡتَ مُؤۡمِنٗا﴾⟪4:94⟫.\n⟦3:1371⟧\nوقوله: ﴿إِنَّ ٱللَّهَ كَانَ عَلَىٰ كُلِّ شَيۡءٍ حَسِيبًا﴾⟪4:86⟫ أي يحاسبكم\nعلى كل شيء قل أو كثر، فلا تتغافلوا عن صغيرة وكبيرة.\nوقول عطاء: حفيظا، وقول ابن جبير: شهيدا فإشارة إلى\nهذا المعنى، وقيل: (حسيبا) أي كافيا، من قولهم:\nأحسبني هذا الشيء - أي كفاني - حتى قلت حسبي.\nومن قال ذلك جعله من باب: الداعي السميع. أي المسمع،\n⟦3:1372⟧\nوفيه (عطاء حسابا) أي كافيا، والمعنى أن الله يعطي كل\nشيء من المعرفة والحفظ والرزق ما يكفيه إذ هو حافظه."}, {"a": [87], "v": 3, "p": 1372, "ev": 3, "ep": 1373, "sid": 1573, "t": "قوله تعالى: (الله لا إله إلا هو ليجمعنكم إلى يوم القيامة لا ريب فيه ومن أصدق من الله حديثا (87)\nسمى يوم القيامة لقوله: ﴿يَوۡمَ يَقُومُ ٱلنَّاسُ لِرَبِّ ٱلۡعَٰلَمِينَ﴾⟪83:6⟫.\nوقوله: ﴿يَوۡمَ يَقُومُ ٱلرُّوحُ وَٱلۡمَلَٰٓئِكَةُ صَفّٗاۖ﴾⟪78:38⟫.\nإن قيل: ما وجه هذه بعد تلك الآية؟\nقيل: لما أمر المسلمين أن يقبلوا من بذل لهم السلام.\nبين لهم بهذه الآية أن ذلك حكم للظاهر.\nفأما السرائر فإن الله يتولاها يوم القيامة.\nتنبيها أن الله لا يحب المنافق أن يغتر بهذا.\nبل يتحقق أن الله له بالمرصاد.\nإن قيل: كيف قاله: ﴿وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِيثٗا﴾⟪4:87⟫\n⟦3:1373⟧\nوما كان صدقا من الحديث لا يتضارب، فيكون من بعض\nقائليه أكثر صدقا من قائل آخر؟\nقيل: إن الصدق من صفة القائل لا من القول.\nوالقائلون إذا اعتبروا بأقوالهم فمنهم من يكون\nصدقه في أحاديثه أكثر، فكأنه قيل إذا اعتبر الصادقون في أقوالهم\nفليس فيهم أكثر صدقا من الله، فإنه لا يقع في خبره كذب بوجه."}, {"a": [88], "v": 3, "p": 1373, "ev": 3, "ep": 1378, "sid": 1574, "t": "قوله عز وجل: (فما لكم في المنافقين فئتين والله أركسهم بما كسبوا أتريدون أن تهدوا من أضل الله ومن يضلل الله فلن تجد له سبيلا (88)\nالركس والنكس: الرذل، والركس أبلغ، لأن النكس ما جعل\nأسفله أعلاه، والركس أصله ما جعل رجيعا بعد أن كان\n⟦3:1374⟧\nطعاما فهو كالرجس، وقد وصف أعمالهم به، كما قال تعالى:\n﴿إِنَّمَا ٱلۡمُشۡرِكُونَ نَجَسٞ﴾⟪9:28⟫.\nويقال: ركسه وأركسه، وأركس أبلغ، كما أن أسقاه أبلغ من قولهم سقاه.\nإن قيل: كيف قال: ﴿فَلَن تَجِدَ لَهُۥ سَبِيلٗا﴾⟪4:88⟫ فنفى نفيا مطلقا، وقد أثبت للكفار سبيلا؟ فقال: ﴿يُقَٰتِلُونَ فِي سَبِيلِ ٱلطَّٰغُوتِ﴾⟪4:76⟫.\nوقال: ﴿وَإِن يَرَوۡاْ سَبِيلَ ٱلۡغَيِّ يَتَّخِذُوهُ سَبِيلٗاۚ﴾⟪7:146⟫؟\nقيل: اسم الجنس إذا أطلق فليس يتناول إلا الصحيح.\nولهذا يقال: لا صلاة إلا بكذا.\nوقالوا: فلان ليس برجل. لما كان أخلاق الرجل تتناول للكامل.\nفلذلك لا يعد قائل ذلك كاذبا.\nواختلف في سبب نزول هذه الآية على\n⟦3:1375⟧\nأوجه: الأول: قال زيد: هي في الذين تخلفوا يوم أحد.\nوقالوا: ﴿لَوۡ نَعۡلَمُ قِتَالٗا لَّٱتَّبَعۡنَٰكُمۡۗ﴾⟪3:167⟫.\nالثاني: قال الحسن ومجاهد: هي في قوم قدموا المدينة وأظهروا الإسلام.\nثم رجعوا إلى مكة فأظهروا الشرك.\nالثالث: قال ابن عباس وقتادة: في\n⟦3:1376⟧\nقوم أسلموا بمكة، ثم أعانوا المشركين على المسلمين.\nالرابع، قال السدي: في قوم بالمدينة أرادوا الخروج منها.\nالخامس: قال ابن زيد: في قوم من أهل الإفك، وما بعده نزل أنه\nفي شأن الهجرة، وجملة الأمر أن الناس كانوا اختلفوا في فئة\nمن المنافقين فئتين، أمنهم بعضهم ووالاهم بعضهم، فقال\nتعالى: ما لكم قد صرتم فئتين مختلفتين فيهم، وقد خذلهم\nالله، فبين أن لا سبيل لهم بعد أن أضلهم الله، كقوله\nتعالى: ﴿إِنَّكَ لَا تَهۡدِي مَنۡ أَحۡبَبۡتَ وَلَٰكِنَّ ٱللَّهَ يَهۡدِي مَن يَشَآءُۚ﴾⟪28:56⟫.\nوقوله: ﴿أَتُرِيدُونَ أَن تَهۡدُواْ مَنۡ أَضَلَّ ٱللَّهُۖ﴾⟪4:88⟫،\n⟦3:1377⟧\nقال الحسن: معناه: أتريدون أن تجعلوا لأهل الضلال ما جعله الله\nلأهل الهدى.\nوقيل: أتريدودن أن تسموهم مهتدين، وقد سماهم الله ضالين.\nوقيل: أتريدون أن تهدوهم كرها وقد جعلهم الله بما اكتسبوه حالا فحالا ضالين، وذلك إشارة إلى نحو قوله: ﴿كـَلَّاۖ بَلۡۜ رَانَ عَلَىٰ قُلُوبِهِم مَّا كَانُواْ يَكۡسِبُونَ﴾⟪83:14⟫.\nوقوله: ﴿بَلۡ طَبَعَ ٱللَّهُ عَلَيۡهَا بِكُفۡرِهِمۡ﴾⟪4:155⟫، وقوله: ﴿وَطَبَعَ ٱللَّهُ عَلَىٰ قُلُوبِهِمۡ﴾⟪9:93⟫\nفقد تقدم أن الله تعالى لما أجرى العادة أن من\nتحرى الخير حالا فحالا ازداد هداية بسبب ذلك نفسه، إذ كان\nفاعل أسباب الشيء قد يقال إنه فاعل للشيء، فإنه هو\nأولى بأن يسمى فاعلا، وقد تقدم الكلام في الهداية والضلال\nبما فيه الكفاية.\nوانتصاب قوله: (فئتين) على\n⟦3:1378⟧\nالحال عند البصريين، وعلى تقدير (كانوا) عند الكوفيين.\nوعلى هذا القولين قولهم: مالك خارجا؟."}, {"a": [89], "v": 3, "p": 1378, "ev": 3, "ep": 1380, "sid": 1579, "t": "قوله تعالى: (ودوا لو تكفرون كما كفروا فتكونون سواء فلا تتخذوا منهم أولياء حتى يهاجروا في سبيل الله فإن تولوا فخذوهم واقتلوهم حيث وجدتموهم ولا تتخذوا منهم وليا ولا نصيرا (89)\nالهجرة: ترك الشيء والإعراض عنه مكانا أو خليطا، وسمي\nالقبيح من الكلام هجرا لكونه مقتضيا لهجره، والرفث\nهاجرة لكونه حاملا على أن يهجره، وسمي المهاجر لتركه\nوطنه، وصار اسم مدح في الإسلام، وسمي من رفض فضولات\nشهواته مهاجرا، عنى تعالى أن الذين تقدم ذكرهم ممن بقوا\nبمكة وادعوا الإسلام أنهم كفار، ويريدون لكم الكفر الذي هم\n⟦3:1379⟧\nعليه، ومن أراد لكم الكفر فمحال موالاتهم، فلا تتخذوهم\nأولياء حتى يسلموا، ويحققوا إسلامهم بالهجرة، ثم قال:\n﴿فَإِن تَوَلَّوۡاْ﴾⟪4:89⟫ أي إن كشفوا الغطاء فقط صاروا مرتدين، ﴿فَخُذُوهُمۡ وَٱقۡتُلُوهُمۡ حَيۡثُ وَجَدتُّمُوهُمۡۖ﴾⟪4:89⟫، ولا تكونن بينكم وبيتهم موالاة ونصر بوجه.\nإن قيل: فما قائدة قوله: ﴿وَلَا تَتَّخِذُواْ مِنۡهُمۡ وَلِيّٗا وَلَا نَصِيرًا﴾⟪4:89⟫ بعد أن قال: ﴿فَلَا تَتَّخِذُواْ مِنۡهُمۡ أَوۡلِيَآءَ﴾⟪4:89⟫؟\nقيل: قد قال بعضهم ذلك على التوكيد، والصحيح أن الذين دخلوا في\nالإسلام من الأعراب فرقتان، فرقة هاجروا وفرقة أقاموا.\nوبين الله تعالى أن من أقام ولم يهاجر فلا ولاء له، إلا أن يستنصروكم\nعلى قومهم فتنصرونهم، وذلك في قوله: ﴿مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَيۡءٍ حَتَّىٰ يُهَاجِرُواْۚ وَإِنِ ٱسۡتَنصَرُوكُمۡ فِي ٱلدِّينِ فَعَلَيۡكُمُ ٱلنَّصۡرُ إِلَّا عَلَىٰ قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞۗ﴾⟪8:72⟫ فمنع تعالى عن موالاتهم بقوله:\n﴿فَلَا تَتَّخِذُواْ مِنۡهُمۡ أَوۡلِيَآءَ﴾⟪4:89⟫ كما منع بتلك الآية، ولم يمنعهم من\nنصرتهم، ثم بين أنهم إن تولوا، أي ارتدوا عما أظهروه من\n⟦3:1380⟧\nالإسلام، وكشفوا الغطاء بالكفر، فلا يجوز أن توالوهم، ولا أن\nتنصروهم بوجه."}, {"a": [90], "v": 3, "p": 1380, "ev": 3, "ep": 1384, "sid": 1581, "t": "قوله تعالى: (إلا الذين يصلون إلى قوم بينكم وبينهم ميثاق أو جاءوكم حصرت صدورهم أن يقاتلوكم أو يقاتلوا قومهم ولو شاء الله لسلطهم عليكم فلقاتلوكم فإن اعتزلوكم فلم يقاتلوكم وألقوا إليكم السلم فما جعل الله لكم عليهم سبيلا (90)\nالحصر: حبس في ضيق، وعبر عن البخل والجبن لانحصار النفس.\nوكذلك عبر عنهما بضيق الصدر وعن ضدهما بسعة الصدر.\nوبالبر المشتق عن البر أي السعة، والحصور الممنوع\nعن الجماع بحبس شهوته، وعن الشراب بحبس ماله لبخله.\nوفي اتصال هذه الآية بما قبلها وحكمتها صعوبة، ووجه ذلك\n⟦3:1381⟧\nأنه لما أمر تعالى الناس فيما تقدم بالهجرة، ونهى عن موالاة من\nتأخر، استثنى بهذه الآية من يحصل له إحدى حالتين؛ إما أن\nيصلوا إلى قوم بينهم وبين النبي - صلى الله عليه وسلم -\nعهد لتعذر لحوقهم به، فيقيموا إلى وقت الإمكان به؛ وإما أن يهاجروا ويأتوا النبي - صلى الله عليه وسلم - والمسلمين\nفتحصر صدورهم أن يقاتلوا المسلمين لعلمهم بكونهم على الحق.\nوأن يقاتلوا قومهم لكونهم غير آمنين على مالهم وذويهم، فهذا\nمعنى قوله: ﴿حَصِرَتۡ صُدُورُهُمۡ أَن يُقَٰتِلُوكُمۡ أَوۡ يُقَٰتِلُواْ قَوۡمَهُمۡۚ﴾⟪4:90⟫.\nوقوله: ﴿وَلَوۡ شَآءَ ٱللَّهُ لَسَلَّطَهُمۡ عَلَيۡكُمۡ﴾⟪4:90⟫ إظهار من الله تعالى لنعمته\nعلى المسلمين وأنه لو لم يهدهم لكانوا في جملة المتسلطين عليكم.\nثم بين أنهم إذ قد اعتزلوا وأظهروا الإسلام فاتركوهم؛ فهذا\nعلى ما ذكر هذا القائل هم الذين أسلموا ولم يستحكم إيمانهم،\n⟦3:1382⟧\nولم يبلغوا الحد الذي لا يحرجون في نصرة الدين إلى أهل.\nوقال قتادة - وقد روي عن ابن عباس: - أن قوله:\n﴿إِلَّا ٱلَّذِينَ يَصِلُونَ إِلَىٰ قَوۡمِۭ﴾⟪4:90⟫ هو في قوم من الكفار\nاعتزلوا المسلمين يوم فتح مكة فلم يكونوا من الكافرين.\nولا مع المسلمين، قال: وهذا معنى ﴿أَوۡ جَآءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ﴾⟪4:90⟫\nقال: ثم نسخ ذلك بآية القتال، والقول الأول أظهر وأحسن.\nوقوله: ﴿حَصِرَتۡ صُدُورُهُمۡ﴾⟪4:90⟫ في موضع الحال عند الفراء.\nقال: وتقديره قد حصرت صدورهم، وتقوى ذلك بقراءة الحسن\n﴿أَوۡ جَآءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ﴾⟪4:90⟫، وقال بعضهم:\n⟦3:1383⟧\nهو خبر بعد خبر، كأنه قيل: أو حصرت صدورهم.\nوقال الجرجاني في كتاب النظم: تقديره: وإن ﴿جَآءُوكُمۡ حَصِرَتۡ صُدُورُهُمۡ﴾⟪4:90⟫ فحذف إن.\nقال: والفعل الماضي يقع في الشرط موقع المستقبل.\nوفيما ادعاه إضمار إن عهدة، فما أرى أهل اللغة يطابقونه عليه.\nوقال المبرد: هو دعاء عليهم، ورد\n⟦3:1384⟧\nذلك أبو علي الفسوي، وقال: قد أمرنا أن نقول:\n\"اللهم أوقع بين الكفار العداوة والبغضاء\".\nفلا يجوز أن يحمل على الدعاء، فيكون في قوله: ﴿أَن يُقَٰتِلُوكُمۡ﴾⟪4:90⟫\nنفي ما اقتضاه دعاء المسلمين عليهم.\nوهذا القول من المبرد ، ومن الراد عليه مبني على أن الآية في الكفار على ما تقدم من القول الثاني فيه.\nولقائل أن يقول: كما يجوز أن يدعى عليهم بإيقاع العداوة.\nيجوز أن يدعى عليهم بأن يجعلهم الله حيث لا يقاتلون أعداءهم\nولا قومهم، ويكون ذلك سؤالا لموتهم، ويدلك على جواز\nذلك أنه لو جمع بين المقاتلين لم يمتنع، فكأن يقال: أوقع بينهم\nالعداوة والبغضاء، وأوهن كيدهم، واجعلهم بحيث لا يقاتلون\nالمسلمين ولا بعضهم بعضا، على أن قوله (قومهم) قد يعبر به\nعمن ليس منهم، بل هم من معاديهم كقولك: فلان صاحبك\nوهم قومك، أي المناصبون لك."}, {"a": [91], "v": 3, "p": 1385, "ev": 3, "ep": 1388, "sid": 1586, "t": "قوله تعالى: (ستجدون آخرين يريدون أن يأمنوكم ويأمنوا قومهم كل ما ردوا إلى الفتنة أركسوا فيها فإن لم يعتزلوكم ويلقوا إليكم السلم ويكفوا أيديهم فخذوهم واقتلوهم حيث ثقفتموهم وأولئكم جعلنا لكم عليهم سلطانا مبينا (91)\nالركس والرجس يتقاربان، لكن الرجس الحس.\nوقيل: ركسه وركزه بمعنى؛ إلا أن الركس يقال في مكروه.\nوقيل: الفتنة هاهنا الكفر، وقيل: الاختبار، والسلطان: الحجة\n⟦3:1386⟧\nوالبطش، وقد تقدم حقيقته.\nوالآية قيل: نزلت في نعيم بن مسعود، وكان ينقل حديث النبي - صلى الله عليه وسلم - إلى كفار مكة.\nوقال ابن عباس: نزلت في قبيلتي أسد وغطفان)،\n⟦3:1387⟧\nوقال قتادة: في حي من تهامة، وجملة الأمر أنه لما ذكر فيما تقدم من له\nعذر بأحد الأمرين اللذين ذكرهما، ذكر هاهنا فرقة لا عذر لهم\nكانوا يظهرون الإسلام ثم يرجعون إلى عبادة الأصنام، كمن\nذكرهم في قوله: ﴿وَإِذَا لَقُواْ ٱلَّذِينَ ءَامَنُواْ قَالُوٓاْ ءَامَنَّا وَإِذَا خَلَوۡاْ إِلَىٰ شَيَٰطِينِهِمۡ قَالُوٓاْ إِنَّا مَعَكُمۡ﴾⟪2:14⟫، فذكر ﴿فَإِن لَّمۡ يَعۡتَزِلُوكُمۡ﴾⟪4:91⟫، ويطلبوا\n⟦3:1388⟧\nبدخولهم الإسلام، ويكفوا أيديهم عنكم، فقد أبيح لكم\nقتلهم، وقد جعل الله لكم عليهم حجة بما بينه.\nوقوله: ﴿كُلَّ مَا رُدُّوٓاْ إِلَى ٱلۡفِتۡنَةِ﴾⟪4:91⟫ أي إذا ردوا إلى الكفر عادوا إليه فتنجسوا به.\nوقيل: إذا ردوا إلى الاختبار أي الإسلام وجدوا يركسون\nفيها، ويكون قوله: (أركسوا) وجدوا كقولهم: أحمدوا\nوأذموأ، وقيل: الفتنة الاختبار إنما أريد به ما قصد بقوله:\n(الم (1) أحسب الناس أن يتركوا أن يقولوا آمنا وهم لا يفتنون).\nومعناه أنه إذا نالتهم محنة ارتدوا، كما قال تعالى: ﴿وَمِنَ ٱلنَّاسِ مَن يَعۡبُدُ ٱللَّهَ عَلَىٰ حَرۡفٖۖ فَإِنۡ أَصَابَهُۥ خَيۡرٌ ٱطۡمَأَنَّ بِهِۦۖ وَإِنۡ أَصَابَتۡهُ فِتۡنَةٌ ٱنقَلَبَ عَلَىٰ وَجۡهِهِۦ خَسِرَ ٱلدُّنۡيَا وَٱلۡأٓخِرَةَۚ﴾⟪22:11⟫ الآية."}, {"a": [92, 93], "v": 3, "p": 1388, "ev": 3, "ep": 1402, "sid": 1589, "t": "قوله تعالى: (وما كان لمؤمن أن يقتل مؤمنا إلا خطأ ومن قتل مؤمنا خطأ فتحرير رقبة مؤمنة ودية مسلمة إلى أهله إلا أن يصدقوا فإن كان من قوم عدو لكم وهو مؤمن فتحرير رقبة مؤمنة وإن كان من قوم بينكم وبينهم ميثاق فدية مسلمة إلى أهله وتحرير رقبة مؤمنة فمن لم يجد فصيام شهرين متتابعين توبة من الله وكان الله عليما حكيما (92)\n⟦3:1389⟧\nإن قيل: هل يجوز أن يقتل المؤمن خطأ حتى قال:\n﴿وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا إِلَّا خَطَـٔٗاۚ﴾⟪4:92⟫؟\nقيل: إن قولك يجوز أو لا يجوز. إنما يقال في الأفعال الاختيارية المقصودة، فأما الخطأ فلا يقال فيه ذلك.\nوقولك: ما كان لك أن تفعل كذا، وقولك: ما كنت لتفعل كذا متقاربان، وهما تعليلان بمعنى، وإن كان أكثر ما يقال للأول لما كان الإحجام عنه من قبل نفسه، ويدل على أنه قد يقال: ما كان لك أن تفعل كذا - لما ذكرنا - قوله: ﴿مَا كَانَ لِلَّهِ أَن يَتَّخِذَ مِن وَلَدٖۖ﴾⟪19:35⟫، لأن معناه: ما كان لله ليتخذ ولدا\nفي أنه لا نهي، وعلى هذا قوله: ﴿مَّا كَانَ لَكُمۡ أَن تُنۢبِتُواْ شَجَرَهَآۗ﴾⟪27:60⟫.\n⟦3:1390⟧\nفقوله: ﴿وَمَا كَانَ لِمُؤۡمِنٍ أَن يَقۡتُلَ مُؤۡمِنًا﴾⟪4:92⟫ أي ما كان المؤمن ليقتل مؤمنا إلا خطأ، وهذا ظاهر، وهذا المعنى أراد من قال معناه: ما ينبغي للمؤمن أن يقتل مؤمنا متعمدا، ولكن يقع ذلك منه خطأ.\nوكذا من قال: ليس في حكم الله أن يقتل المؤمن مؤمنا إلا خطأ.\nوقال الأصم: معناه ليس القتل لمؤمن بمتروك لا يقتص له إلا\nأن يكون قتله خطأ، وهذا يرجع إلى الأول.\nوقول بعض النحويين: إن هذا استثناء خارج فليس على التقدير الذي\nذكرناه، كذلك، بل هو واجب، وذكر على بن موسى القمي\n⟦3:1391⟧\nأن معنى ذلك: ليس للمؤمن أن يقتل مؤمنا إلا أن يراه في دار\nالحرب، فيظنه كافرا فيقتله خطأ، فيكون الخطأ راجعا إلى القاتل\nفي كونه غير عالم بحال المقتول، وأما من قال: معنى (إلا خطأ) ولا خطأ، واستدلاله بقول الشاعر:\nوكل أخ مفارقه أخوه. . . لعمر أبيك إلا الفرقدان\nأي: ولا الفرقدان، فذلك تشبيه فيه ما أرى أن محققي\n⟦3:1392⟧\nالنحويين يوافقونه.\nوقيل: الخطأ في الأصل على وجوه، منها:\nأن يقع بلا قصد من القاتل إلى القتل، ولا إلى الإتيان به بوجه.\nكمن سقط من يده شيء فأصاب نفسه فقتله، ومنها أن يقصد\nإصابة الشيء غير المقتول، فاتفق إصابته فقتله، كمن يرمي صيدا\nفأصاب إنسانا فقتله، أو يقصده ولكن لا بسلاح يقتل مثله، أو\nيقصده بسلاح لكن لا يريد قتله، أو يقصده بسلاح ويريد قتله\nلكن لا يعلمه محظور القتل، كمن يرمي مسلما في صف المشركين.\nأو يقصده بسلاح ويريد قتله لا في دار الحرب، لكن القاصد غير\nمكلف كالصبي والمجنون، وكل ذلك يقال له: قتل الخطأ، لكن\nلذلك تعارف في الشرع هو المراعى، وقد وبين ذلك في كتب الفقه.\nوالرقبة المؤمنة: أن يكون مولودا في دار الإسلام صغيرا كان أو\n⟦3:1393⟧\nكبيرا، أو سباه من دار الحرب مسلم قبل البلوغ، أو أسلم بعد\nالبلوغ، وهذا الإيمان هو الإسلام، دون كمال الإيمان المتقدم\nذكره في غير هذا الموضع.\nقال الحسن: ما في القرآن مؤمنة فلا يجزئ إلا من صام وصلى وحسن إسلامه، وما عدا ذلك فيجزئ فيه الصغير والكبير.\nوقال إبراهيم: لا يجزئ في ذلك إلا البالغ.\nوقدر الدية مختلف فيه والمفزع فيه إلى السنة.\nوظاهر الآية يقتضي شيئا مقدرا.\nوالتتابع في صيام الشهرين مشروط، والظاهر\n⟦3:1394⟧\nأن ما لا يمكن الاحتراز منه لا يبطل التتابع كالحيض والمرض\nالطارئ والإغماء، وأما مصادفة الأيام التي حظر فيها الصوم\nكيوم العيد، وأيام التشريق، والإفطار في السفر، أو الشهر الذي\nيستحق صومه بالشرع كشهر رمضان، فإن ذلك يقطع التتابع.\nويوجب الاستئناف، وحكي عن مسروق أن ﴿فَمَن لَّمۡ يَجِدۡ فَصِيَامُ شَهۡرَيۡنِ﴾⟪4:92⟫ عنى من لم يجد الدية والرقبة، وسائر أهل العلم بخلافه.\nفالدية حق الآدميين، والكفارة حق\n⟦3:1395⟧\nالله، فلا تنوب إحداهما عن الأخرى.\nوقال الأصم: ظاهر الكتاب يدل على أن الدية تلزم القاتل.\nلأنه قال: ﴿فَدِيَةٞ مُّسَلَّمَةٌ إِلَىٰٓ أَهۡلِهِۦ﴾⟪4:92⟫ فعطفها على الكفارة.\nومعناه: عليه ذلك.\nوإنما بين النبي - صلى الله عليه وسلم - أن دية الخطأ تتحمل العاقلة عن\nالقاتل على سبيل المواساة، لا أنه نسخ الكتاب بالسنة.\nوقوله: ﴿إِلَّآ أَن يَصَّدَّقُواْۚ﴾⟪4:92⟫ أي: يعفوا عن الدية، فجعل العفو\nعنها صدقة منهم، تنبيها على فضيلة العفو وحثا عليه، وأنه جار\nمجرى الصدقة في استحقاق الثواب الآجل به دون طلب العوض\n⟦3:1396⟧\nالعاجل، وهذا حكم من قتل في دار الإسلام خطأ.\nوقوله:\n﴿فَإِن كَانَ مِن قَوۡمٍ عَدُوّٖ لَّكُمۡ وَهُوَ مُؤۡمِنٞ﴾⟪4:92⟫ أي من أهل\nالحرب في الدار والمعركة، وفي فقد التمييز لا في معنى القرابة.\nولا فرق بين أن يكون مسلما دخل دار الحرب، أو أسلم هناك ولم\nيهاجر.\nوقيل: قد دخل في ذلك من أسلم في دار الإسلام من\nالمشركين ولم يعلم القاتل به.\nوخبر الحارث يدل على ذلك، لأنه قتل بالمدينة وقد كان أسلم.\nوقيل: إنما أسقط الدية فيه إذا كان أولياؤه كفارا وهو مؤمن.\nفإن ديته راجعة إلى المؤمنين\n⟦3:1397⟧\nفلا معنى لإلزامهم.\nوقوله: ﴿وَإِن كَانَ مِن قَوۡمِۭ بَيۡنَكُمۡ وَبَيۡنَهُم مِّيثَٰقٞ﴾⟪4:92⟫\nأي كان المقتول خطأ من قوم كذلك.\nواختلفوا هل الإيمان شرط فيه؟\nفقال الحسن ومالك: هو شرط، تقديره: إن كان المقتول خطأ مؤمنا.\nقال مالك: ولا كفارة في قتل الذمي.\nومنهم من قال: الآية واردة فيمن\n⟦3:1398⟧\nكان بينه وبين النبي - صلى الله عليه وسلم - عهد فاسلم.\nثم قتله مسلم من غير حرب، قالوا: وكان هذا في زمن الرسول\n- صلى الله عليه وسلم -، فأما بعد فقد أمروا بقتالهم.\nومنهم من قال: عنى بالميثاق الذمة إما بالعهد أو الاستئمان.\nوالظاهر أن كل قتل في عهد جائز بين المسلمين ففيه الدية والكفارة.\nوتعلق هذه الآية بما قبلها هو أنه لما ذكر فيما قبلها حكم من أسلم فمنعه عذر من مقابلة أعداء المسلمين، وحكم من لم يسلم، وإنما يريد أن يسلم على\n⟦3:1399⟧\nالفريقين، فأمر في الأولى بالتجافي وفي الثانية بقتلهم، بين هاهنا\nخطر قتل المؤمنين، وجعلهم صنفين: مقتولا خطأ، ومقتولا\nعمدا. فبين حكم الخطأ وجعل المقتولين ثلاثة أصناف على ما\nفسرناه، ثم بين حكم قتل العمد، فقال تعالى:\n(ومن يقتل مؤمنا متعمدا فجزاؤه جهنم خالدا فيها وغضب الله عليه ولعنه وأعد له عذابا عظيما (93)\nالعمد: فعل الشيء عن إرادة واختيار، ويضاده الخطأ.\nوصفة قتل العمد أن يقصده بحديدة أو حجر يقتل غالبا، أو توبع\nعليه بخنق أو بسوط فتوالى عليه حتى يموت.\nوالآية قيل نزلت في رجل فقده الكفار، وذاك أنه خرج في سرية\nفنزلوا ماء، فخرج من أصحابه عليه السلام رجل فحمل عليه فقتله.\nوقيل: هي في رجل رآه أخوه مقتولا في بني النجار،\n⟦3:1400⟧\nفشكا إلى النبي - صلى الله عليه وسلم - فأمر أن تدفع إليه الدية فدفعت\nإليه، ثم حمل على مسلم فقتله فهرب إلى مكة، ولا خلاف بين\nعامة المسلمين أن التائب يخرج من هذا الحكم، وقد روي عن\n⟦3:1401⟧\nالنبي - صلى الله عليه وسلم - أن رجلا جاء فقال: هل للقاتل توبة؟\nفقال: \"نعم \".\nثم جاءه آخر فسأله عن ذلك، فقال: \"لا توبة له \"، فراجعه بعض\nأصحابه في ذلك، فقال: \"إن الأول كان قد قتل فكرهت أن\nأؤيسه من رحمة الله، فيتملكه الشيطان فيهلكه، وأما الثاني فرأيته\nعازما على قتل رجل اعتمادا على أن يتوب من بعد، فكرهت أن\nيمني عزيمته \".\nوأهل الوعيد يجرون الآية على العموم، ويخصصون به قوله: ﴿إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ وَيَغۡفِرُ مَا دُونَ ذَٰلِكَ لِمَن يَشَآءُۚ﴾.\nومخالفوهم يخصصون قوله: ﴿وَمَن يَقۡتُلۡ مُؤۡمِنٗا مُّتَعَمِّدٗا﴾⟪4:93⟫ بقوله:\n﴿إِنَّ ٱللَّهَ لَا يَغۡفِرُ أَن يُشۡرَكَ بِهِۦ﴾ الآية، ويجرون تلك على العموم.\nوالمفزع لمن يريد تحقيق ذلك إلى غير الآيتين، والله أعلم.\n⟦3:1402⟧\nوقد تقدم أن القصد بغضبه تعالى إلى إنزال عقابه.\nدون تغير حال يعتري ذاته تعالى الله عن التغيرات.\nولعنته في الدنيا: إبعاده من لعنه عن الصفات النفيسة التي\nيتخصص به أولياؤه، وفي الآخرة عقابه وتبعيده عن ثوابه."}, {"a": [94], "v": 3, "p": 1402, "ev": 3, "ep": 1405, "sid": 1603, "t": "قوله عز وجل: (يا أيها الذين آمنوا إذا ضربتم في سبيل الله فتبينوا ولا تقولوا لمن ألقى إليكم السلام لست مؤمنا تبتغون عرض الحياة الدنيا فعند الله مغانم كثيرة كذلك كنتم من قبل فمن الله عليكم فتبينوا إن الله كان بما تعملون خبيرا (94)\nقرئت: (تثبتوا) و (تبينوا)، وقيل: التبين أبلغ؛ لأنه قل ما يكون إلا بعد التثبت، وقد يكون التثبت\n⟦3:1403⟧\nولا تبين، وقد قوبل بالعجلة في قولهم: التبين من الله، والعجلة\nمن الشيطان فتبينوا، وقرئ (السلم) و (السلام).\nوالسلام قيل: التحية، وقيل: الاستسلام.\nوالسلم والسلم: الصلح.\nوقيل: هو بمعنى الإسلام، ويقال للصلح: السلم، فلا يكون مرادا هاهنا، لأن المسلم مخير إذا طلب الكافر منه السلم بين أن يبذله له، وبين أن يمنعه، وروي أنه خرج مقداد في سريته فمر برجل في غنيمات، فقال: إني مسلم.\n⟦3:1404⟧\nفلم يلتفت إلى قوله، فقتله وأخذ غنيماته، فلما رجع إلى النبي - صلى الله عليه وسلم - أنكره، فقال: \"هلا شققت عن قلبه \".\nوالآية تدل على أن المجتهد في مسائل الاجتهاد معذور، ولولا ذلك لما قاره النبي - صلى الله عليه وسلم -.\n⟦3:1405⟧\nوقرأ أبو جعفر: (لست مأمنا) أي مبذولا له الأمان."}, {"a": [95, 96], "v": 3, "p": 1405, "ev": 3, "ep": 1411, "sid": 1606, "t": "قوله عز وجل: (لا يستوي القاعدون من المؤمنين غير أولي الضرر والمجاهدون في سبيل الله بأموالهم وأنفسهم فضل الله المجاهدين بأموالهم وأنفسهم على القاعدين درجة وكلا وعد الله الحسنى وفضل الله المجاهدين على القاعدين أجرا عظيما (95) درجات منه ومغفرة ورحمة وكان الله غفورا رحيما (96)\nالدرجة معروفة، ومنها أدرجت الكتاب: طويته طيا\nيشبه الإدراج، و (غير) يوصف به النكرة، وما فيه الألف\nواللام إذا دل على الجنس، وقد يستثنى\n⟦3:1406⟧\nبه، فإذا قرئ منصوبا فعلى الاستثناء أو على الحال، وإذا\nجر فصفة للمؤمنين، وإذا رفع فصفة للقاعدين.\nوالضرر: اسم عام لكل ما يضر بالإنسان في بدنه ونفسه.\nوعلى سبيل الكفاية عبر عن الأعمى بالضرير.\nفإن قيل: كيف يصح حمله على الأمراض \"النفسية.\nوقد قال في ذم الكفار: ﴿فِي قُلُوبِهِم مَّرَضٞ﴾؟\nقيل: إن الذي عذرهم الله تعالى فيه هو ما لم يكن الإنسان نفسه سببه.\nوما ذموا به فهو المرض، أي الجهل الذي يكون هو سبب استجلابه من ترك إصغائه إلى\n⟦3:1407⟧\nالحق، وإهمال نفسه من العادات الجميلة.\nولذلك قال ابن عباس أولي الضرر: هم أهل العذر، فعمم.\nوقد ذكر عامة ما أجمله هاهنا في قوله: ﴿لَّيۡسَ عَلَى ٱلۡأَعۡمَىٰ حَرَجٞ﴾ الآية.\nإن قيل: لم كرر الفضل وأوجب في الأول درجة، وفي الثاني درجات.\nوقيدها بقوله: (منه)، وجعل معها المغفرة والرحمة؟\nقيل: في ذلك أجوبة: الأول:\nأنه عنى بالدرجة ما يؤتيه في الدنيا من الغنيمة، ومن السرور بالظفر وجميل الذكر، وبالثاني ما يخولهم في الآخرة، ونبه بإفراد الأول، وجمع الثاتي أن ثواب الدنيا في جنب ثواب الآخرة يسير.\nوالثاني: أن المجاهدين في ثواب الدنيا يتساوون فيما يتناولونه، كمن يأخذ سلب مقتوله، وكتساوي نصيب كل واحد من الفرسان، ونصيب كل واحد من الرجالة، وهم في الآخرة يتفاوتون بحسب إيمانهم، فلهم درجات\nحسب استحقاقه، ومنهم من يكون له الغفران، ومنهم من تكون له\n⟦3:1408⟧\nالرحمة فقط، وكأن الرحمة أدنى المنازل، والمغفرة فوق الرحمة، ثم بعده\nالدرجات على الطبقات، وعلى هذا نبه بقو له: ﴿هُمۡ دَرَجَٰتٌ عِندَ ٱللَّهِۗ﴾⟪3:163⟫.\nومنازل الآخرة تتفاوت، وقد نبه على ذلك بنحو قوله:\n﴿وَٱلسَّٰبِقُونَ ٱلۡأَوَّلُونَ﴾⟪9:100⟫ إلى قوله: ﴿ٱنظُرۡ كَيۡفَ فَضَّلۡنَا بَعۡضَهُمۡ عَلَىٰ بَعۡضٖۚ﴾⟪17:21⟫. والثالث: أن الجهاد جهادان: صغير وكبير.\nفالصغير مجاهدة الكفار، والكبير مجاهدة النفس، وعلى ذلك دل\nقوله عليه الصلاة والسلام: \"رجعنا من جهاد الأصغر إلى جهاد\nالأكبر \".\nوبقوله: \"جهادك هواك\".\n⟦3:1409⟧\nوإنما كان مجاهدة النفس أعظم، لأن من جاهد\nنفسه فقد جاهد الدنيا، ومن غلب الدنيا هان عليه مجاهدة العدى.\nفخص بمجاهدة النفس بالدرجات تعظيما لها.\nوالرابع: أن الأول عنى به الجهاد بالمال، والثاني الجهاد بالنفس.\nإن قيل: لم ذكر مع الدرجات المغفرة والرحمة معا؟ وما الفرق بينهما؟\nقيل: إن المغفرة تقال اعتبارا بإزالة الذنوب، والرحمة تقال اعتبارا بإيجاب التوبة، وإدخال الجنة،\n⟦3:1410⟧\nوالدرجات هي: المنازل الرفيعة بعد إدخال الجنة.\nوقيل: إن الرحمة هي: أن يتوب عليه أمن، الذنب وإن كان بعد تبكيت\nوعقاب، والمغفرة هي: أن يستر ذنوبه فلا تبكيت به.\nوالدرجات: هو أن يجعل لكل واحد درجة بقدر ما يليق به.\nوهي المعبرة عنها بالغرفات، وقد قال عليه الصلاة والسلام:\n\"إن في الجنة مائة درجة، ما بين كل درجتين كما بين السماء والأرض.\nأعد الله أعلاها للمجاهدين في سبيله \"، فقال رجل: ما الدرجة؟\nفقال عليه الصلاة والسلام: \"أما إنها ليست بعتبة\".\n⟦3:1411⟧\nإن قيل: كيف قال: ﴿وَكُلّٗا وَعَدَ ٱللَّهُ ٱلۡحُسۡنَىٰۚ﴾⟪4:95⟫ والكفار من جملة الكل؟\nقيل: إن كلا هاهنا لم تتناول إلا من تقدم ذكره من المؤمنين والمجاهدين\nوالقاعدين."}, {"a": [97, 98, 99], "v": 3, "p": 1411, "ev": 3, "ep": 1414, "sid": 1612, "t": "قوله: (إن الذين توفاهم الملائكة ظالمي أنفسهم قالوا فيم كنتم قالوا كنا مستضعفين في الأرض قالوا ألم تكن أرض الله واسعة فتهاجروا فيها فأولئك مأواهم جهنم وساءت مصيرا (97) إلا المستضعفين من الرجال والنساء والولدان لا يستطيعون حيلة ولا يهتدون سبيلا (98) فأولئك عسى الله أن يعفو عنهم وكان الله عفوا غفورا (99)\n(توفاهم) قيل: هو ماض، وقيل: تقديره تتوفاهم الملائكة.\nوذلك في وصف قوم أظهروا الإسلام ولم يهاجروا.\nبل كثروا سواد المشركين يوم بدر فقتلوا،\n⟦3:1412⟧\nفادعوا لما سألهم الملائكة الذين توفوهم أنهم كانوا مستضعفين.\nفكذبهم الله، وقيل: هم الذين نهى عن موالاتهم بقوله:\n﴿وَٱلَّذِينَ ءَامَنُواْ وَلَمۡ يُهَاجِرُواْ مَا لَكُم مِّن وَلَٰيَتِهِم مِّن شَيۡءٍ حَتَّىٰ يُهَاجِرُواْۚ﴾⟪8:72⟫\nإن قيل: كيف لم يعذرهم لما اعتذروا بالاستضعاف وقد قال\nمن قبل: (إلا المستضعفين)؟\nقيل: لأنهم كذبوا في دعواهم، والذين عذرهم هم الذين سلبهم الله القوى والقدرة، أو لم يعطهم ذلك كالصبي.\nوقال بعض المحققين: ظلم النفس في الحقيقة هو التقصير في تهذيبها وسياستها المذكورة في قوله: ﴿وَقَدۡ خَابَ مَن دَسَّىٰهَا﴾⟪91:10⟫ وذلك أن كل إنسان\nسائس نفسه، فمتى لم يوف حق السياسة\n⟦3:1413⟧\nفقد ظلمها ظلم الوالي رعيته، قال: وخاطب بذلك من أعطاه\nالقوة ومكنه أن يبلغ الدرجات الرفيعة، فرضي لنفسه بأخس\nمنزلة، وكذبهم فيما ادعوه من استضعافهم تنبيها أن من أمكنه\nاستفادة ما به يقدر فهو في حكم القادر فلا يعذر ، ثم استثنى\nالأصناف الثلاثة فقال: ﴿فَأُوْلَٰٓئِكَ عَسَى ٱللَّهُ أَن يَعۡفُوَ عَنۡهُمۡۚ﴾⟪4:99⟫\nفذكر لفظ عسى لئلا يركنوا كل الركون، وليكونوا ممن قال\nفيهم: ﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾⟪17:57⟫.\nوقوله: ﴿وَكَانَ ٱللَّهُ عَفُوًّا غَفُورٗا﴾⟪4:99⟫\nأخر ذكر الغفران إذ هو أبلغ، وقد تقدم أن\n⟦3:1414⟧\nالوصفين إذا اجتمعا يقدم الأعم ويؤخر الأخص، تنبيه\nعلى أن مثل هذه الصفة ليست على وجه المطابقة، واعتبارا\nلحصول المعفو عنه والمغفور له، بل ذلك له على وجه أشرف من\nذلك، والله أعلم."}, {"a": [100], "v": 3, "p": 1414, "ev": 3, "ep": 1416, "sid": 1615, "t": "قوله عز وجل: (ومن يهاجر في سبيل الله يجد في الأرض مراغما كثيرا وسعة ومن يخرج من بيته مهاجرا إلى الله ورسوله ثم يدركه الموت فقد وقع أجره على الله وكان الله غفورا رحيما (100)\nالمراغم: المتحرك إما من الرغام أي التراب.\nوقيل: هو من رغم أنفه إذا غضب.\nوالمراد به قريب من قول الشاعر:\n⟦3:1415⟧\nإذا كنت في دار يهينك أهلها. . . ولم تك ممنوعا بها فتحول\nوقيل: نزل ذلك في رجل من بني ضمرة كان مريضا.\nفقال: أخرجوني، فأشرف في الطريق، وقيل: إنه أخذ يمينه\nبشماله وقال: قد بايعتك يارسول الله، فبين تعالى أن\nالمهاجر وإن لم يبلغ المقصد فله بذلك ثواب، وكذا من نوى\n⟦3:1416⟧\nخيرا وعاقه عائق عن إتمامه."}, {"a": [101], "v": 3, "p": 1416, "ev": 3, "ep": 1419, "sid": 1617, "t": "قوله عز وجل: (وإذا ضربتم في الأرض فليس عليكم جناح أن تقصروا من الصلاة إن خفتم أن يفتنكم الذين كفروا إن الكافرين كانوا لكم عدوا مبينا (101)\nالضرب في الأرض من قولهم: ضرب العرق ضربا.\nإذا أسرع التحرك، والفتنة: المحنة وذلك يشتبه.\nلذلك استعمل في القتل والإحراق، ولأجل عمومها قال:\n﴿وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ﴾⟪2:191⟫، لأن الفتنة قد تكون قتلا، وما هو أعظم من\nالقتل)، وأهل الحجاز يقولون: فتنته، وأهل نجد يقولون:\nافتنته ففتن فتونا.\nقال أبو عبيدة يقال: قصرت الصلاة\n⟦3:1417⟧\nوقصرتها وأقيصرتها.\nوالعدو يقال للوا حد وللجمع، كقوله: ﴿فَإِنَّهُمۡ عَدُوّٞ لِّيٓ﴾⟪26:77⟫\nواشترط في القصر السفر والخوف.\nوقيل: إنه لما سأل عمر رضي الله عنه النبي - صلى الله عليه وسلم -:\nما بالنا نقصر وقد أمنا؟ قال:\n\"صدقة تصدق الله عليكم بها، فاقبلوا صدقته \".\n⟦3:1418⟧\nوالقصر: قيل: عنى به الهيئات وأن صلاة المسافر ركعتان\nتامتان، وذلك عن عمر وعائشة، وقيل: عنى قصر الركعات\nعما عليه في الحضر، قال ابن عباس وجابر: إن صلاة الحضر\nأربع، والسفر ركعتان، والخوف ركعة، والضرب في الأرض\n⟦3:1419⟧\nبعضهم يجعله على التعارف، ويعتبره بما يسمى سفرا.\nولا خلاف أن الخارج إلى قرية بظاهر البلد لا يجوز له القصر.\nوبعضهم قيده بمسيرة ثلاثة أيام بناء على تحديد مسح المسافر\nوتحريم سفر المرأة بغير ذي محرم، وبعضهم حده بثمانية وأربعين ميلا، اعتبارا بسفر النبي عليه الصلاة والسلام.\nوظاهر الآية يقتضي أن لا فرق بين الحج والجهاد وغيره من\nالأسفار، ولا بين المطيع والعاصي."}, {"a": [102], "v": 3, "p": 1420, "ev": 3, "ep": 1422, "sid": 1621, "t": "قوله تعالى: (وإذا كنت فيهم فأقمت لهم الصلاة فلتقم طائفة منهم معك وليأخذوا أسلحتهم فإذا سجدوا فليكونوا من ورائكم ولتأت طائفة أخرى لم يصلوا فليصلوا معك وليأخذوا حذرهم وأسلحتهم ود الذين كفروا لو تغفلون عن أسلحتكم وأمتعتكم فيميلون عليكم ميلة واحدة ولا جناح عليكم إن كان بكم أذى من مطر أو كنتم مرضى أن تضعوا أسلحتكم وخذوا حذركم إن الله أعد للكافرين عذابا مهينا (102)\nقد علمنا تعالى كيف نصلي صلاة الخوف، فظاهر الآية يقتضي\nما قال ابن عباس: إن الإمام يلي بكل فرقة صلاة تامة، وهم\nيصلون صلاتهم) في سائر الأوقات.\nوقيل: كانت الرخصة في\n⟦3:1421⟧\nذلك للنبي - صلى الله عليه وسلم - فقط لفضل الجماعة معه.\nومذهب عامة الفقهاء على خلاف ذلك، وكيفية صلاة الخوف، والخلاف فيها مبينة في كتب الفقه.\nوقال من يذهب إلى وجوب الجماعة: إن في شرع صلاة الخوف تنبيها على وجوب الجماعة،\n⟦3:1422⟧\nوقيل: في صلاة الخوف تنبيه على أن العمل القليل لا يبطل الصلاة.\nوأن تأخير أداء الصلاة عن وقتها لا يجوز، وأن إقامة الصلاة\nكانت إلى النبي - صلى الله عليه وسلم - مادام فيهم.\nونبه تعالى بقوله: ﴿وَدَّ ٱلَّذِينَ كَفَرُواْ﴾⟪4:102⟫ بما لأجله أمر بتناول الأسلحة للتحرز، وأن في حال المرض والمطر يجوز وضع الأسلحة."}, {"a": [103], "v": 3, "p": 1422, "ev": 3, "ep": 1424, "sid": 1623, "t": "قوله تعالى: (فإذا قضيتم الصلاة فاذكروا الله قياما وقعودا وعلى جنوبكم فإذا اطمأننتم فأقيموا الصلاة إن الصلاة كانت على المؤمنين كتابا موقوتا (103)\n⟦3:1423⟧\nقيل: إن قوله: ﴿فَٱذۡكُرُواْ ٱللَّهَ﴾⟪4:103⟫، وارد في صلاة المريض.\nوالآية تقتضي غير ذلك، لأنه قال: ﴿فَإِذَا قَضَيۡتُمُ ٱلصَّلَوٰةَ﴾⟪4:103⟫.\nاللهم إلا أن يقول قائل ذلك: هو مثل قوله: ﴿فَإِذَا قَرَأۡتَ ٱلۡقُرۡءَانَ فَٱسۡتَعِذۡ بِٱللَّهِ﴾⟪16:98⟫ أي إذا أردت قراءة القرآن.\nوقيل: هو حث على ذكر الله تسبيحا وتعظيما، كقوله: (فسبحان الله حين تمسون وحين تصبحون.\nوقوله: (موقوتا) أي مؤدى في أوقاته،\n⟦3:1424⟧\nوقيل: منجما في أوقاته، قال ابن عباس في هذه الآية وفي\nقوله: ﴿أَقِمِ ٱلصَّلَوٰةَ لِدُلُوكِ ٱلشَّمۡسِ﴾⟪17:78⟫\nإن الآيتين متضمنتمان لأوقات الصلاة مجملة، وأن السنة شرحتها."}, {"a": [104], "v": 3, "p": 1424, "ev": 3, "ep": 1425, "sid": 1625, "t": "قوله تعالى: (ولا تهنوا في ابتغاء القوم إن تكونوا تألمون فإنهم يألمون كما تألمون وترجون من الله ما لا يرجون وكان الله عليما حكيما (104)\nلما كان بناء الكلام على فرض الجهاد، وكان ذكر الصلاة\nكالاعتراض عاد إلى ما كان في ذكره، فقال: ﴿وَلَا تَهِنُواْ فِي ٱبۡتِغَآءِ ٱلۡقَوۡمِۖ﴾⟪4:104⟫ والوهن: ضعف مع فتور)، وعاتبهم، فكأنه قال:\n⟦3:1425⟧\nإذا تساويتم في الألم وزدتم عليهم في أن حصل لكم من الرجاء ما\nلم يحصل لهم، وعرفتم كون الله عليما بما يفعلونه حكيما فيما\nأمركم به فأمركم إذا أعلى، فيجب أن تكون قلوبكم أقوى.\nوالآية يقاربها قول الشاعر وإن كان هي أبلغ:\nقاتلي القوم يا خزاع ولا يد. . . خلكم من قتالهم فشل\nالقوم أمثالكم لهم شعر في ال. . . رأس لا ينشرون إن قتلوا"}, {"a": [105, 106], "v": 3, "p": 1425, "ev": 3, "ep": 1426, "sid": 1626, "t": "قوله تعالي: (إنا أنزلنا إليك الكتاب بالحق لتحكم بين الناس بما أراك الله ولا تكن للخائنين خصيما (105) واستغفر الله إن الله كان غفورا رحيما (106)\n⟦3:1426⟧\nقيل: نزل ذلك في أنصاري سرق درعا لعمه، فاتهم بها فرئي\nفي دار يهودي فأوهم القوم أن اليهودي سرقها، فأعان قوم من\nالمسلمين هذا الأنصاري، فاعتمد النبي - صلى الله عليه وسلم - قولهم، فأطلعه الله على الأمر، وعاتبه، وأمر بالاستغفار مما هم به.\nقال ابن بحر: يجوز أن تكون هذه الآية راجعة إلى قوله: (ألم تر إلى الذين يزعمون أنهم آمنوا بما أنزل إليك وما أنزل من قبلك يريدون أن يتحاكموا إلى الطاغوت وقد أمروا أن يكفروا به ويريد الشيطان أن يضلهم ضلالا بعيدا (60) وإذا قيل لهم تعالوا)\nفبين أنهم مع إظهارهم الإيمان بما أنزل على الأنبياء يصدون عما\nيدعون إليه من حكم الكتاب.\nقال: ومعنى ﴿وَلَا تَكُن لِّلۡخَآئِنِينَ خَصِيمٗا﴾⟪4:105⟫ راجع إلى قوله: ﴿فَمَا لَكُمۡ فِي ٱلۡمُنَٰفِقِينَ فِئَتَيۡنِ وَٱللَّهُ أَرۡكَسَهُم بِمَا كَسَبُوٓاْۚ﴾⟪4:88⟫، فنهى عن حسن الظن بأمثالهم، ونهى في هذه الآية عن الدفع عنهم."}, {"a": [107, 108], "v": 3, "p": 1427, "ev": 3, "ep": 1429, "sid": 1628, "t": "قوله تعالى: (ولا تجادل عن الذين يختانون أنفسهم إن الله لا يحب من كان خوانا أثيما (107) يستخفون من الناس ولا يستخفون من الله وهو معهم إذ يبيتون ما لا يرضى من القول وكان الله بما يعملون محيطا (108)\nأعاد النهي عن الذب عنهم بقوله: ﴿وَلَا تُجَٰدِلۡ﴾⟪4:107⟫\nوالمجادلة: المقاتلة، من قولهم: جدلت الخيل، وقيل: المنازعة من الإلقاء\nعلى الجدالة والجدال المطلق مذموم، ولهذا لم يطلقه للنبي - صلى الله عليه وسلم - حتى قيده، قال: ﴿وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ﴾⟪16:125⟫.\nوالاختيان: افتعال من الخيانة، واختيانهم أنفسهم\n⟦3:1428⟧\nجعلهم إياها خائنة بما يفعلونه، كقولك: ظلم نفسه.\nإن قيل: لم خص لفظ الخوان بنفي المحبة عنه، وهو لا يحب الخائن أيضا؟\nوقيل: تخصيصه هاهنا تعريض بهم، وتعظيم لفعلهم.\nوتنبيه أن من يتحرى خيانة ولا يستمر عليها فهو معرض أن يقلع\nفيحبه، ومتى استمر عليها صار مطبوعا على قلبه، لا يقلع\nفترجى له المحبة، فإذا الخائن قد يكون محبوبا على وجه.\nوالخوان لا يكون محبوبا بوجه.\nوقوله تعالى: ﴿يَسۡتَخۡفُونَ مِنَ ٱلنَّاسِ وَلَا يَسۡتَخۡفُونَ مِنَ ٱللَّهِ﴾⟪4:108⟫\nأي الخونة أبدا يسترون على أنفسهم خيانتهم، لكون قبحها مركوزا في\nنفوسهم، ونبه أنهم إن ستروها على الناس فليست تستتر على الله.\n⟦3:1429⟧\nوأنهم لنقصهم وجهلهم بالله يراعون الناس أكثر\nمن مراعاتهم لعظمة الله، وإلى نحو هذا أشار النبي\nعليه الصلاة والسلام بقوله:\n\"استحيوا من الله كما تستحيون من أحدكم \".\nوهذا قريب من قوله: ﴿وَيَقُولُونَ طَاعَةٞ فَإِذَا بَرَزُواْ مِنۡ عِندِكَ بَيَّتَ طَآئِفَةٞ مِّنۡهُمۡ غَيۡرَ ٱلَّذِي تَقُولُۖ﴾⟪4:81⟫ الآية.\nوقوله: ﴿وَهُوَ مَعَهُمۡ﴾⟪4:108⟫ نحو ﴿إِنَّ ٱللَّهَ لَا يَخۡفَىٰ عَلَيۡهِ شَيۡءٞ فِي ٱلۡأَرۡضِ وَلَا فِي ٱلسَّمَآءِ﴾⟪3:5⟫.\nقال ابن مسعود: من صلى صلاة عند الناس لا يصلي مثلها إذا خلى فقد استهان بالله. ثم تلا هذه الآية."}, {"a": [109], "v": 3, "p": 1430, "ev": 3, "ep": 1430, "sid": 1631, "t": "قوله عز وجل: (ها أنتم هؤلاء جادلتم عنهم في الحياة الدنيا فمن يجادل الله عنهم يوم القيامة أم من يكون عليهم وكيلا (109)\nخاطب الذابين عن هذا الخائن، ونبه أنكم وإن اعتقدتم\nالذب عنه في الدنيا وستر خيانته، فالشأن في يوم القيامة عند من\nلا تخفى عليه خافية، وحيث لا ينفع إلا من أتى الله بقلب سليم.\nومن فسر الوكيل بالكفيل فتفسير عام بخاص، فإن الكفيل\nوكيل ما، وليس كل وكيل كفيلا."}, {"a": [110], "v": 3, "p": 1430, "ev": 3, "ep": 1432, "sid": 1631, "t": "قوله تعالى: (ومن يعمل سوءا أو يظلم نفسه ثم يستغفر الله يجد الله غفورا رحيما (110)\nعامل السوء وظالم النفس وإن كانا يعودان إلى معنى واحد،\n⟦3:1431⟧\nفذكرهما اعتبارا بحالتين، وقيل: عمل السوء إشارة إلى فعل\nالصغائر، وظلم النفس إلى الكبائر.\nوقوله: ﴿ثُمَّ يَسۡتَغۡفِرِ ٱللَّهَ﴾⟪4:110⟫ راجع إليه دون الأول.\nفكأنه قيل: من فعل صغيرة أو استغفر من كبيرة يجد الله غفورا رحيما. وقيل: عمل الإساءة ما يفعل بالغير، وظلم النفس ما يختص به الإنسان من ذنب لا يتعداه.\n⟦3:1432⟧\nوقد تقدم الكلام في السوء والسيئات، ومقابلتهما بالحسنات."}, {"a": [111], "v": 3, "p": 1432, "ev": 3, "ep": 1433, "sid": 1633, "t": "قوله عز وجل: (ومن يكسب إثما فإنما يكسبه على نفسه وكان الله عليما حكيما (111)\nالأصل في الاكتساب ما يجر به نفع، فاستعاره لما يجلب ضرا.\nتنبيها أن صاحبه يقدر فيما تحراه أنه يكسب خيرا وهو يكسب\nشرا، ونحوه معنى قوله: ﴿إِنۡ أَحۡسَنتُمۡ أَحۡسَنتُمۡ لِأَنفُسِكُمۡۖ وَإِنۡ أَسَأۡتُمۡ فَلَهَاۚ﴾⟪17:7⟫.\n⟦3:1433⟧\nوقوله: (من عمل صالحا فلنفسه ومن أساء فعليها.\nونبه بقوله: ﴿وَكَانَ ٱللَّهُ عَلِيمًا حَكِيمٗا﴾⟪4:111⟫ على نحو\nقوله: ﴿يَعۡلَمُ مَا تَكۡسِبُ كُلُّ نَفۡسٖۗ وَسَيَعۡلَمُ ٱلۡكُفَّٰرُ لِمَنۡ عُقۡبَى ٱلدَّارِ﴾⟪13:42⟫."}, {"a": [112], "v": 3, "p": 1433, "ev": 3, "ep": 1434, "sid": 1634, "t": "قوله تعالى: (ومن يكسب خطيئة أو إثما ثم يرم به بريئا فقد احتمل بهتانا وإثما مبينا (112)\nعنى بالخطيئة ما لا يكون عن عمد، وبالإثم ما كان عن\nعمد، ونبه أن من رمى بأحدهما بريئا فهو في استحقاق العقاب\nسواء، وإن كان في ارتكاب أحدهما بخلاف الآخر.\nوبين أنه يحصل له بذلك معاقبة مرتكب البهتان، ومعاقبة مرتكب الإثم.\nوذلك تعظيم لنسبة الإنسان ما ارتكبه إلى غيره عمدا كان أو خطأ.\nقال ابن بحر: إن ذلك يرجع إلى المنافقين الذين حكى\n⟦3:1434⟧\n﴿وَإِن تُصِبۡهُمۡ حَسَنَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِ ٱللَّهِۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَقُولُواْ هَٰذِهِۦ مِنۡ عِندِكَۚ﴾⟪4:78⟫، فقال تعالى في رده ﴿قُلۡ كُلّٞ مِّنۡ عِندِ ٱللَّهِۖ فَمَالِ هَٰٓؤُلَآءِ ٱلۡقَوۡمِ لَا يَكَادُونَ يَفۡقَهُونَ حَدِيثٗا﴾⟪4:78⟫.\nوقال تعالى في آل عمر ان: ﴿إِنَّ ٱلَّذِينَ تَوَلَّوۡاْ مِنكُمۡ يَوۡمَ ٱلۡتَقَى ٱلۡجَمۡعَانِ إِنَّمَا ٱسۡتَزَلَّهُمُ ٱلشَّيۡطَٰنُ بِبَعۡضِ مَا كَسَبُواْۖ وَلَقَدۡ عَفَا ٱللَّهُ عَنۡهُمۡۗ﴾⟪3:155⟫، فبين بالآيتين أن الذي أصابهم عقوبة لما كان منهم، وأنه عفا عنهم، وبين هاهنا أن من\nأضاف ما أصابه من سوء في متوجهاته إلى النبي فقد أتى ببهتان وإثم."}, {"a": [113], "v": 3, "p": 1434, "ev": 4, "ep": 146, "sid": 1635, "t": "قوله تعالى: (ولولا فضل الله عليك ورحمته لهمت طائفة منهم أن يضلوك وما يضلون إلا أنفسهم وما يضرونك من شيء وأنزل الله عليك الكتاب والحكمة وعلمك ما لم تكن تعلم وكان فضل الله عليك عظيما (113)\nكان همهم أن يضلوه بشهادتهم للأنصاري أنه برئ مما قرن\n⟦3:1435⟧\nبه، ومسألتهم إياه أن يقوم بعذره، وقد تقدم الكلام في\nالفرق بين الكلام والحكمة.\nوذكر ابن بحر وجهين:\nأحدهما: لولا فضل الله بما أنزله من الكتاب والحكمة لهم\nالكافرون بإضلاله وإدخاله معهم في عبادة الأصنام، لكن لما هداه\nصاروا لا يضلونه، بل يضلون أنفسهم.\nوالثاني: أن الإضلال عبارة عن الإهلاك، كقول الشاعر:\nفآب مضلوه بخمر جلبه. . . وغودر بالحولان حزم وقائل\n⟦3:1436⟧\nأي لولا أن الله حرسك لهم طائفة بإهلاكك، وما يهلكون بما\nيفعلون إلا أنفسهم بما يكسبون لها من العذاب الدائم.\nإن قيل: قد كانوا هموا بذلك فكيف قال: ﴿وَلَوۡلَا فَضۡلُ ٱللَّهِ عَلَيۡكَ وَرَحۡمَتُهُۥ لَهَمَّت طَّآئِفَةٞ﴾⟪4:113⟫؟\nقيل: في ذلك جوابان:\nأحدها: أن القوم كانوا مسلمين، ولم يهموا بإضلال النبي - صلى الله عليه وسلم -، فقد كان عندهم على الصواب.\nوالثاني: أن القصد إلى نفي تأثير ما هموا به كقولك: فلان شتمك، وأهانك، لولا أني تداركت، تنبيها أن أثر فعله لم يظهر.\n⟦4:146⟧\nبسم الله الرحمن الرحيم\nالجزء الرابع\nالكتاب: تفسير الراغب الأصفهاني\n(من الآية 114 من سورة النساء - وحتى آخر سورة المائدة)\nتحقيق ودراسة: د. هند بنت محمد بن زاهد سردار\nالناشر: كلية الدعوة وأصول الدين - جامعة أم القرى\nالطبعة الأولى: 1422 ه - 2001 م\nعدد الأجزاء: 2\n[ترقيم الكتاب موافق للمطبوع]"}, {"a": [114], "v": 4, "p": 147, "ev": 4, "ep": 151, "sid": 1639, "t": "قوله تعالى: (لا خير في كثير من نجواهم إلا من أمر بصدقة أو معروف أو إصلاح بين الناس ومن يفعل ذلك ابتغاء مرضات الله فسوف نؤتيه أجرا عظيما (114)\nيقال: لكل ما يستحسنه العقل ويعترف به معروف، ولكل ما يستقبحه وينكره منكر، ووجه ذلك أن الله ركز في العقول معرفة الخير والشر وإليها أشار بقوله: ﴿صِبۡغَةَ ٱللَّهِ﴾⟪2:138⟫ و (فطرت الله) وعلى ذلك البر: ما اطمأن إليه القلب واطمأنت إليه النفس، واطمئنانها إليه لمعرفتها به.\n⟦4:148⟧\nوالنجوى: تقال للحديث الذي تفرد به اثنان فصاعدا أو للقوم المتنلجين،\nقوله تعالى: ﴿وَإِذۡ هُمۡ نَجۡوَىٰٓ﴾⟪17:47⟫ وأصل ذلك من النجوه، والنجاة:\nأي الخلاص منها لكون الملتجي إليها ناجيا عن السبيل ويقال: هو في مضية\nوتلفة من النوب، ولما كان المتناجيان كثيرا ما ينتبذان في نجوة، قيل انتجيا\n⟦4:149⟧\nوالنجا السرعة كقولهم: ارتفع في المسير ونجوت الجلد، لقولهم: رفعت عنه\nالجلد، وإذا جعل النجوى للقوم فمن مجرور على البدل أومنصوب على\nالاستثناء، وإن جعلتها للحديث فتقديره: لا نجوى من أمر بصدقة، ولما كان\nالتناجى مكروها في الأصل حتى قال: ﴿إِنَّمَا ٱلنَّجۡوَىٰ مِنَ ٱلشَّيۡطَٰنِ﴾⟪58:10⟫ صار ذلك من الأفعال التي تقبح ما لم يقصد به وجه محمود\n⟦4:150⟧\nكالمكر والخديعة، فبين تعالى أن النجوى لا تحسن ما لم تخص بها هذه الوجوه\nالمستثناه.\nفإن قيل: فهاهنا أفعال أخر تحسن فلم خص هذه الثلاثة؟\nقيل هذه الثلاثة متضمنة للأفعال الحسنة كلها وذلك أنه نبه بالصدقة على الأفعال الواجبة وخص الصدقة لكونها أكثر نفعا في إيصال الخير إلى الغير، ونبه بالمعروف على النوافل التي هى الإحسان والتفضل وبالإصلاح بين الناس على سياستهم\nوما يؤدي إلى نظم كلهم وإيقاع الألفة بينهم، ذلك أفضل الأفعال لقول النبي - صلى الله عليه وسلم -: \" ألا أخبركم بأفضل من درجة الصلاة والصيام والصدقة، قيل بلى يا رسول الله، قال: صلاح ذات البين \".\nفإن قيل: فلم خص من أمر بهذه الأشياء دون من تولاها بنفسه وتوليها أبلغ من الأمر بها؟\nقيل: في ضمن ذلك توليها، وذاك أنه إذا كان الآمر بالمعروف يستحق الحمد فمتوليه معلوم أنه مستحق لذلك، فكأنه قيل إن من تولي ذلك وآمن به، ونبه بقوله:\n⟦4:151⟧\n﴿وَمَن يَفۡعَلۡ ذَٰلِكَ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِ﴾⟪4:114⟫ أن أفعال الخير يستحق بها\nالأجر العظيم إذا قصد بها وجه الله، لا أن يفعل رياء وسمعة واستجلاب منفعة أو محمدة من الناس، ووصف الأجر بالعظيم تنببها على حقارة ما يفوت في جنبه من أعراض الدنيا."}, {"a": [115], "v": 4, "p": 151, "ev": 4, "ep": 154, "sid": 1643, "t": "قوله تعالى: (ومن يشاقق الرسول من بعد ما تبين له الهدى ويتبع غير سبيل المؤمنين نوله ما تولى ونصله جهنم وساءت مصيرا (115)\nالشق: القطع طولا ومنه استعير\nالاشتقاق، وشق العصا وشق عليه الأمر كقولهم مشقة الأمر، وشق كرددت\nعصاه، ومشاقة الرسول أن يصير في شق غير شقة كقوله: ﴿إِنَّ ٱلَّذِينَ يُحَآدُّونَ ٱللَّهَ وَرَسُولَهُۥ﴾ أي يصيرون في حد غير حده، وذلك\nأشبه بالاعتقاد والديانة، وأصل الصلا الملازمة، ومنه الصلاة للدعاء ومن أجله قول النبي - صلى الله عليه وسلم -: (ايصلوا يا ذا الجلال والإكرام) أي الزموا مراعاة ذلك،\n⟦4:152⟧\nوالصلا: ملازمة قرب النار للاصطلاء بها فجعل عبارة عن ملازمتها للعذاب\n، والصلوان العرقان المكتنفان لجانبي الوركين، يجوز أنه اعتبر فيهما الاصطلاء\nكتسمية اليد والرجل المصطلى، والآية قيل: نزلت في سارق الدرع حيث\nأظهر النبي - صلى الله عليه وسلم - حاله فأنكر وكذب، وقيل: في طعمة بن الأبيرق لما عبد الأوثان، ولما ذكر قيل: ﴿وَمَن يَعۡمَلۡ سُوٓءًا أَوۡ يَظۡلِمۡ نَفۡسَهُۥ ثُمَّ يَسۡتَغۡفِرِ ٱللَّهَ﴾⟪4:110⟫\n⟦4:153⟧\nذكر هنا من عمل ذلك ولم يستغفر، وعظم تعالى من يشاقق\nالرسول بعد ما تبين الحق له، وعلى هذا قال بعض الحكماء: صغائر الأولياء\nأعظم من كبائر العامة، وذاك أنه لا يعذر العالم فيما يرتكبه كما يعذر الجاهل.\nفإن قيل ولم كان العالم أكبر جرما؟\nقيل: لأن من لا يعرف الحق يستحق العقوبة بترك المعرفة، لأن العمل لا يلزمه حتى يعرفه أو يعرف من يصدقه، والعالم يستحق بترك معرفته وترك استعماله، فإذن هو أعظم جرما.\nوقصد تعالى بقوله: ﴿نُوَلِّهِۦ مَا تَوَلَّىٰ وَنُصۡلِهِۦ جَهَنَّمَۖ﴾⟪4:115⟫ أن من لم يتبين له\nالهدى فقد جعل الله له نورا يهديه، ومن صار معاندا قطع عنه التوفيق وتركه\nهو وهواه، وانقطاع التوفيق هو المعني باللعن والطرد وإليه أشار الشاعر\nبقوله: -\nإذا لم يكن عون من الله للفتى ... فأكثر ما يجني عليه اجتهاده\nوبين بقوله: ﴿وَسَآءَتۡ مَصِيرًا﴾⟪4:115⟫ عظم حالها في العقاب، واستدل\n⟦4:154⟧\nبالآية على ثبوت الإجماع، وقيل: إن الله عظم وعيد من يتبع غيرسبيل\nالمؤمنين \" ولا حجة في ذلك لأن المراد بقوله (المؤمنين) الإيمان لا ذويه،\nفكل موصوف بوصف علق به حكم نحو أن يقال: اسلك سبيل الصائمين والمصلين، يعني بذلك الحث على الاقتداء بهم في الصلاة والصيام، لا في فعل\nآخر، فكما إذا قيل سبيل المؤمنين يعني به سبيلهم في الإيمان لا غير."}, {"a": [116], "v": 4, "p": 154, "ev": 4, "ep": 157, "sid": 1646, "t": "قوله تعالى (إن الله لا يغفر أن يشرك به ويغفر ما دون ذلك لمن يشاء ومن يشرك بالله فقد ضل ضلالا بعيدا (116)\nإن قيل: لم لم يشترط فيه التوبة؟\nقيل: إن المشرك إنما يلزمه الاسم ما دام يلزمه الوصف، فإذا زال\n⟦4:155⟧\nوصفه زال اسم الشرك عنه، فإذا كان كذلك، فالمشرك ما دام مشركا لا يغفر له، ومن تاب زال عنه اسم الشرك، فإذا التائب الذي يغفر له ليس هو المشرك، بل هو المؤمن في الحقيقة، ومن أطلق عليه اسم المشرك فعلى اعتبار الماضي، وقوله: ﴿أَن يُشۡرَكَ بِهِۦ﴾⟪4:116⟫ موضعه النصب، كأنه قال: لا يغفر الشرك، وقيل: لا يغفر من أجل أن يشرك به، أي لا يغفر من أجل الشرك شيئا من\nالذنوب تنبيها، أن الذنوب قد تغتفر مع انتفاء الشرك، كما قال: ﴿إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ﴾⟪7:56⟫، وقوله: ﴿ضَلَٰلَۢا بَعِيدًا﴾⟪4:116⟫\nفقد تقدم أن الحق والصواب والعدالة وغيرها من وجوه البر تجري مجرى\n⟦4:156⟧\nالنقطة من الدائرة ومجرى المقرطس من المريء، وأن ما عداه كله باطل\nوضلال، لكن منه ما هو قريب ومنه ما هو بعيد، كما أن العدول عن المقرطس قد يكون قريبا، وقد يكون بعيدا، كذلك العدول عن الحق يكون قريبا وبعيدا، ولهذا قيل: سمى الله ذنوب الأنبياء، وفجور الكفار حميعاالضلال، وإن كان بينهما بون بعيد، ولما كان كذلك وكان أفظع الضلال الشرك بالله، نبه بقوله: ﴿ضَلَٰلَۢا بَعِيدًا﴾⟪4:116⟫ أن الشرك إذا اعتبر بسائر الضلالات، فهو أكبرهن وأعظمهن، فإن متحريه قد يضل عن الطريق المستقيم ضلالا يصعب رجوعه إليه، فإن مرتكب الذنب الصغير يجري مجرى الضال عن الطريق القريب يرجى عوده إليه، ومن قال إن هذه الآية مجمله، فإنه يجب أن يبني على قوله: ﴿إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ نُكَفِّرۡ عَنكُمۡ سَيِّـَٔاتِكُمۡ وَنُدۡخِلۡكُم مُّدۡخَلٗا كَرِيمٗا﴾⟪4:31⟫ وإن بناء هذه على تلك يقتضي أن\nيغفر ما دونها من الصغائر، فهذا تشبيه منه وترك للظاهر، فإنه تعالى بين أنه\n⟦4:157⟧\nلا يغفر الشرك، وأنه يغفر ما دون الشرك لكن منهم المغفور له، وعلق بمشيئته فظاهره يقتضي أن الشرك لا يغفر لا محاله، لكن الشبهة في أعيان المغفور لهم الا في الذنب المغفور وهذا ظاهر."}, {"a": [117, 118, 119, 120], "v": 4, "p": 157, "ev": 4, "ep": 167, "sid": 1649, "t": "قوله تعالى: (إن يدعون من دونه إلا إناثا وإن يدعون إلا شيطانا مريدا (117) لعنه الله وقال لأتخذن من عبادك نصيبا مفروضا (118) ولأضلنهم ولأمنينهم ولآمرنهم فليبتكن آذان الأنعام ولآمرنهم فليغيرن خلق الله ومن يتخذ الشيطان وليا من دون الله فقد خسر خسرانا مبينا (119) يعدهم ويمنيهم وما يعدهم الشيطان إلا غرورا (120).\nمن المفسرين، من اعتبر التأنيث ها هنا في اللفظ دون المعنى، وقال: لما كان اسم معبوداتهم مؤنثة نحو اللات، والعزى ونحو الملائكة، سماها مؤنثا تسميتهم الأذنين والخصيتين والأنثيين، حتى قال الشاعر:\n...............\nضربناه تحت الأنثيين على الكرد\n⟦4:158⟧\nأي وتحت الأذنين.\nوقال آخر:\nوما ذكر فإن تسمن فأنثى ... شديد الأذم ليس له بذي ضروس\nوعني بذلك القراد لأنه ما دام صغيرا يقال له القراد، وذلك لفظ مذكر،\nوإذا كبر يقال له يقاريد، وذلك لفظ مؤنث، فجعله مؤنثا مذكر، ومنهم من اعتبر التأنيث من حيث المعنى وقال: الموجودات بإضافة بعضها إلى بعض ثلاثة أضرب: فاعل غير منفعل وذلك هو الباري تعالى فقط، ومنفعل غير فاعل وذلك هو للجمادات، ومنفعل من وجه فاعل من وجه هو الإنسان، فإنه بالإضافة إلى الله منفعل وبالإضافة إلى مصنوعاته فاعل، وعلى هذا الوجه\n⟦4:159⟧\nمذاهب العرب في التأنيث والتذكير فقالوا: الواحدي ذكر واحدة أنثى،\nقال: وقد علم أن أكثر ما عبده العرب من الأصنام كانت أشياء منفعلة غير\nفاعلة، فبكتهم الله تعالى أنهم مع كونهم فاعلين من وجه يعبدون ما ليس هو إلا منفعلا من كل وجه، وعلى هذا نبه إبراهيم بقوله: (إذ قال لأبيه يا أبت لم تعبد ما لا يسمع ولا يبصر ولا يغني عنك شيئا (42)\nوقول السلف: يقتضي الأمرين فقد اتفق: أبو مالك والسدي\n⟦4:160⟧\nوابن زيد (الإناث اللات والعزى) وقال: ابن عباس والحسن\nوقتادة: هي الأموات، وهذا القول يقتضي أنهم اعتبروا التأنيث في المعنى\n⟦4:161⟧\nوقال الضحاك: هي الملائكة لزعمهم أنها بنات الله، وقرأ ابن عباس (إلا\nأنثا) أي وثنا، وهى جمع الوثن، والمارد، والمريد الذي لا يعلق بشيء من\nالفضائل، و (صرح ممرد). أي مملس لا يعلق به شيء لملاسته، وشجرة مرداء اعتبارا بتعريها عن الورق، وغلام أمرد لتعريه عن الشعر، تعرى\n⟦4:162⟧\nالشجر عن الورق.\nإن قيل: كيف قال: - ﴿إِن يَدۡعُونَ مِن دُونِهِۦٓ إِلَّآ إِنَٰثٗا﴾⟪4:117⟫ ثم قال: ﴿وَإِن يَدۡعُونَ إِلَّا شَيۡطَٰنٗا مَّرِيدٗا﴾⟪4:117⟫ فاقتضى نفي ما أثبت؟\nقيل: ليس في ذلك نفي فإن دعاء هم للأوثان دعاؤهم للشيطان،\nوكل باطل قال له تارة الشيطان، وتارة الهوى، وتارة الصنم، لما كانت هذه\nالأشياء متلازمة ومتشاركة في أنها تدعو إلى باطل، ولما كان عبادة الشيطان في نفوسهم قطعية، تبين لهم أن ما تدعونه وتزعمونه أنكم تقصدون به عبادة الله، وتقولون: ﴿مَا نَعۡبُدُهُمۡ إِلَّا لِيُقَرِّبُونَآ إِلَى ٱللَّهِ زُلۡفَىٰٓ﴾⟪39:3⟫ وتقصدون\nبه الشيطان، ثم قال: ﴿لَّعَنَهُ ٱللَّهُۘ﴾⟪4:118⟫ التفاتا، وصرف الكلام إلى وصف\nالشيطان، وقوله: ﴿لَأَتَّخِذَنَّ مِنۡ عِبَادِكَ﴾⟪4:118⟫ وذلك إما حكاية عما\nأورده نطقا، أو عما أتاه فعلا، فيكون نحو:\nامتلأ الحوض وقال قطني\n................\n⟦4:163⟧\nومعنى قوله: (مفروضا) معلوما مقسوما، وقيل: مقطوعا\nمنهم، وهم الذين سباهم الشيطان، ووصفهم بقوله: ﴿وَلَقَدۡ صَدَّقَ عَلَيۡهِمۡ إِبۡلِيسُ ظَنَّهُۥ﴾⟪34:20⟫ والبتك: القطع على سبيل التفريق، وبتك الآذان؟\nقيل:\nهو الذي كانوا يفعلونه بالبحيرة، روي ذلك عن السدي، وقتادة، وعكرمة: وقيل: فيه إشارة إلى كل ما جعله الله كاملا بفطرته، فجعله\n⟦4:164⟧\nالإنسان ناقصا بسوء تدبره، وذاك أن الإنسان بالقوة مخلوق خلقة كاملة، قد رشحه الله أن يزكي نفسه ومن دساها فقد خسسها، وتغيير خلق الله هو أن كل ما أوجده الله لفضيلة فاستعان الإنسان به في رذيلة فقد غير خلقه، وقد دخل في عمومه جعل الله للإنسان من شهوة للجماع، ليكون سببا للتناسل على وجه غصوص فاستعان به في السفاح واللواط، وذلك تغيير خلق الله تعالى، وكذا المخنث إذا نتف لحيته وتقنع تشبها بالنساء، والفتاة إذا ترجلت متشبة بالفتيان، ودخل في عمومه أيضا كل ما حلله الله تعالى فحرموه، أو حرمه فحللوه، وعلى ذلك قوله: (قل أرأيتم ما أنزل الله لكم من رزق فجعلتم منه حراما وحلالا قل آلله أذن لكم أم على الله تفترون (59)\nوإلى هذه الجملة أشار المفسرون، وقد روى عن الحمن أنه قال: هو تغيير أحكام الله، ومن قال مرة: هو الوشم إشارة إلى\n⟦4:165⟧\nضرب التغيرات ليتبين به الغرض.\nوكذا من قال بالخصاء، قول: ﴿لَا تَبۡدِيلَ لِخَلۡقِ ٱللَّهِۚ ذَٰلِكَ ٱلدِّينُ ٱلۡقَيِّمُ﴾⟪30:30⟫\nلفظه خبر ومعناه نهي، وقوله تعالى: ﴿وَمَن يَتَّخِذِ ٱلشَّيۡطَٰنَ وَلِيّٗا مِّن دُونِ ٱللَّهِ﴾⟪4:119⟫ فموالاة الإنسان غيره تكون على وجهين:\nأحدهما: أن يقصد موالاته، والثاني: أن لا يقصد موالاته، لكن يقع منه ما\nيرجع إلى صاحبه نفع فهو مواليه فعلا وإن لم يكن مواليه قصدا، وعلى هذا\nالمعاداة فقد يعادي الإنسان غيره قصدا، وقد يقصد موالاته لكن يقع منه ما\nيرجع إليه ضرره فهو معاد له فعلا، وإن لم يكن معاد له قصدا، وعلى هذا\n⟦4:166⟧\n﴿إِنَّ مِنۡ أَزۡوَٰجِكُمۡ وَأَوۡلَٰدِكُمۡ عَدُوّٗا لَّكُمۡ فَٱحۡذَرُوهُمۡۚ﴾⟪64:14⟫\nفاتخاذ الإنسان الشيطان مولى هو على الوجه الثاني، فإن الإنسان لا يقصد بفعله موالاة الشيطان.\nفإن قيل : كيف قال: ﴿مِّن دُونِ ٱللَّهِ﴾⟪4:119⟫ واتخاذ الشيطان\nوليا مع الله مذموم، كاتخاذه من دون الله؟\nقيل: لم يقصد بالآية هذا المقصد، وإنما أريد من ترك تحري موالاة، وفعل ما أدى به إلى موالاة الشيطان، فخسرانه ظاهر لا يتكتم على ذي بصيرة، وقوله: ﴿يَعِدُهُمۡ وَيُمَنِّيهِمۡۖ﴾⟪4:120⟫ تحذير، وهذا الوعد من الشيطان تارة بالإرادات الودية، والخواطر الفاسدة، حسب ما ذكر في كتاب الذريعة إلى مكارم الشريعة، وتارة بلسان أولياء الشيطان، وسبب إمكان وصول ذلك إليه كون القوة المفكرة عمياء من تدبر نور الله، وقد تقدم الكلام في حقيقة الأمنية، وأما سبب الحسد، والنميمة، والظلم، وسائر الرذائل، والغرور: إظهار ما تعذر، من ظاهره فيه نفع، وأصله: الأثر الظاهر من الشيء لشيء غره حسنه مخالفة باطنه، ومن هذه سمى الدنيا\n⟦4:167⟧\nغرورا، فبين أن الشيطان لا يعدهم إلا الدنيا وزخارفها، وقد قال تعالى:\n﴿وَمَا هَٰذِهِ ٱلۡحَيَوٰةُ ٱلدُّنۡيَآ إِلَّا لَهۡوٞ وَلَعِبٞۚ﴾⟪29:64⟫"}, {"a": [121], "v": 4, "p": 167, "ev": 4, "ep": 167, "sid": 1659, "t": "قوله تعالى: (أولئك مأواهم جهنم ولا يجدون عنها محيصا (121)\nالمحيص: المعدل على سبيل الهرب، بين أن هؤلاء صاروا في أسر الشيطان، وكما لم يتفكروا من مولاته في الدنيا، لم يتفكروا من مصاحبته في مقره في\nالآخرة، كما قال تعالى: ﴿ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ﴾⟪37:22⟫."}, {"a": [122], "v": 4, "p": 167, "ev": 4, "ep": 168, "sid": 1659, "t": "قوله تعالى: (والذين آمنوا وعملوا الصالحات سندخلهم جنات تجري من تحتها الأنهار خالدين فيها أبدا وعد الله حقا ومن أصدق من الله قيلا (122)\nقد تقدم الكلام في نحوه، فبين أنه قد وعد بذلك في غير موضع من كتاب، بل في غير كتاب، وإذا كان هذا وعده، والوعد ضرب من القيل، وقد ثبت أنه أصدق قيلا، فإذا هو أصدق وعدا، ونحوه ﴿وَمَنۡ أَصۡدَقُ مِنَ ٱللَّهِ حَدِيثٗا﴾⟪4:87⟫\n⟦4:168⟧\nوقوله: ﴿إِنَّ ٱللَّهَ لَا يُخۡلِفُ ٱلۡمِيعَادَ﴾."}, {"a": [123, 124], "v": 4, "p": 168, "ev": 4, "ep": 171, "sid": 1660, "t": "وقوله تعالى: (ليس بأمانيكم ولا أماني أهل الكتاب من يعمل سوءا يجز به ولا يجد له من دون الله وليا ولا نصيرا (123) ومن يعمل من الصالحات من ذكر أو أنثى وهو مؤمن فأولئك يدخلون الجنة ولا يظلمون نقيرا (124)\nقد تقدم الكلام في حقيقة الأمنية، ولما كان\nأكثر ذلك قولا صادرا عن تخمين ، لا عن تحقيق، جعل عما تخمن، قال الضحاك: كما أخذ كل فرقة تقول قولا لا على مقتضى العلم.\nكما قال تعالى: ﴿وَقَالَتِ ٱلۡيَهُودُ لَيۡسَتِ ٱلنَّصَٰرَىٰ عَلَىٰ شَيۡءٖ﴾⟪2:113⟫ الآية.\n﴿وَقَالُواْ لَن تَمَسَّنَا ٱلنَّارُ إِلَّآ أَيَّامٗا مَّعۡدُودَةٗۚ﴾⟪2:80⟫ وقوله: ﴿فَخَلَفَ مِنۢ بَعۡدِهِمۡ خَلۡفٞ وَرِثُواْ ٱلۡكِتَٰبَ يَأۡخُذُونَ عَرَضَ هَٰذَا ٱلۡأَدۡنَىٰ وَيَقُولُونَ سَيُغۡفَرُ لَنَا وَإِن يَأۡتِهِمۡ عَرَضٞ مِّثۡلُهُۥ يَأۡخُذُوهُۚ﴾⟪7:169⟫ وخاطبهم مستجهلا لهم، كما روى:\n\" ليس الإيمان بالتمني ولا بالتحلي ولكن ما وقر في القلب وصدقه العمل). وقوله تعالى: ﴿مَن يَعۡمَلۡ سُوٓءٗا يُجۡزَ بِهِۦ﴾⟪4:123⟫\n⟦4:169⟧\nقال الحسن وابن زيد: هو في الكفار لأنهم مؤاخذون بصغائرهم وكبائرهم،\nوقيل: هي الكبائر، وقيل: هو عام في جميع الناس، فإن من حصل منه سيء\nجوزي به إما في الدنيا وإما في الآخرة، وقد روي أنه لما نزلت هذه الآية قال أبو بكر رضي الله عنه: (فمن ينجوا مع هذا يا رسول الله؟\n⟦4:170⟧\nفقال عليه الصلاة والسلام: أما تحزن أما تمرض، أما يصيبك\nاللأواء، قال: بلى يا رسول الله، قال: هو ذاك \"\nوقد روي: \" أن الأمراض تمحيص \"\n⟦4:171⟧\nوكما أنه نبه أن شيئا من السيئات لا يبقى غير مجازى\nبه أيضا، وذكر الذكر والأنثى على التوكيد، وقيل: نبه بذكرهما، على سبيل المثل للسايس، والمسوس فيسمى المسوس أنثى، كما سماها الله تعالى زوجا، في قوله: ﴿ٱحۡشُرُواْ ٱلَّذِينَ ظَلَمُواْ وَأَزۡوَٰجَهُمۡ﴾⟪37:22⟫، ونبه بقوله:\n﴿وَلَا يُظۡلَمُونَ نَقِيرٗا﴾⟪4:124⟫، أنهم كانوا جوزوا بالشر فإنهم يجازون\nبالخير، فإنهم إن لم يجازوا بذلك فقد ظلموا ظلما عظيما، والله تعالى متره عن صغير الظلم فكيف عن كبيره.\nإن قيل: لم أطلق في الأول فقال: ﴿مَن يَعۡمَلۡ سُوٓءٗا يُجۡزَ بِهِۦ﴾⟪4:123⟫، وقيد في الثاني فقال: (مؤمن)؟\nقيل: تنبيها أن عمل السوء يضر على كل حال، وأن يجزى للصالحات لا اعتداد به إلا مضامة الإيمان."}, {"a": [125, 126], "v": 4, "p": 172, "ev": 4, "ep": 177, "sid": 1664, "t": "قوله تعالى: (ومن أحسن دينا ممن أسلم وجهه لله وهو محسن واتبع ملة إبراهيم حنيفا واتخذ الله إبراهيم خليلا (125) ولله ما في السماوات وما في الأرض وكان الله بكل شيء محيطا (126)\nالدين، والملة، والإسلام واحد من وجه، لكن يقال باعتبارات مختلفة، فإن\nالدين: هو الانقياد للحق وذلك معتبر بالعبد، والملة: القود إلى الحق من أمللت عليه الكتاب، وذلك معتبر بالله تعالى، وعلى نحوه قالوا: ﴿فَهِيَ تُمۡلَىٰ عَلَيۡهِ بُكۡرَةٗ وَأَصِيلٗا﴾⟪25:5⟫، وقال ابن بحر: هو أن يعدو الذئب على\nشيء ضربا من العدو، فجعله اسما معتبرا أيضا بالعبد كالدين، وكأنه من نحو\nقوله: ﴿إِنِّي ذَاهِبٌ إِلَىٰ رَبِّي سَيَهۡدِينِ﴾⟪37:99⟫، وقوله قال:\n⟦4:173⟧\n﴿وَعَجِلۡتُ إِلَيۡكَ رَبِّ لِتَرۡضَىٰ﴾⟪20:84⟫، والأول هو الوجه، والإسلام: يقال للإسلام\nالحق والدخول في السلم والسلامة من جهة الله تعالى، والحنيفى؟\nقيل: هو\nالمستقيم الطريقه، ومنه الأحنف: للمايل الرجل على سبيل التفاؤل، وقيل\nحنف أي: مال، وسمى إبراهيم حنيفا من حيث مال عما عليه جمهور قومه\nمن المذاهب الباطلة، ولهذا قال تعالى: ﴿إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ قَانِتٗا لِّلَّهِ حَنِيفٗا﴾⟪16:120⟫، ونبه بقوله ﴿وَلَمۡ يَكُ مِنَ ٱلۡمُشۡرِكِينَ﴾⟪16:120⟫ أن عدوله عنهم\nلم يكن على وجه مذموم، وإسلام الوجه لله الإخلاص للعبادة، كما قال\nتعالى: ﴿وَأَخۡلَصُواْ دِينَهُمۡ لِلَّهِ﴾⟪4:146⟫ والذي مدح به إبراهيم عليه الصلاة\nوالسلام هاهنا هو الذي حكى عنه، في قوله عنه: ﴿إِنِّي وَجَّهۡتُ وَجۡهِيَ لِلَّذِي فَطَرَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ حَنِيفٗاۖ وَمَآ أَنَا۠ مِنَ ٱلۡمُشۡرِكِينَ﴾⟪6:79⟫ وهذا هو الإخلاص الذي هو أعظم مرتبة الإيمان\n⟦4:174⟧\n، كالمذكور في قوله عليه الصلاة والسلام (الإيمان بضع وسبعون درجة)،\nومتحروا هذه المترلة هم المستثنون في قوله: (وما يؤمن أكثرهم بالله إلا وهم مشركون (106).\nبين تعالى في هذه الآية أن تمام حسن الانقياد لله\nالإخلاص له مع الإحسان، أي تعاطي مكارم الشريعة فضلا عن الأحكام التي\nهي العدالة، وقيل: معنى (وهو محسن) أي: حسن أن يسلم وجهه لله\n، منبها على فضيلة العلم، ونبه بلفظ الاستحسان في قوله: ﴿وَمَنۡ أَحۡسَنُ دِينٗا﴾⟪4:125⟫ أن ذلك غاية ما يبلغه قوة البشر، ثم قال: - ﴿وَٱتَّبَعَ مِلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۗ﴾⟪4:125⟫ أي إذا فعل هذا فقد اتبعه، وتخصيصه أن كلا من الأمم\nادعى على ملة إبراهيم، فبين أنه بهذا يصير على ملته، وقيل معنى:\n﴿وَٱتَّبَعَ مِلَّةَ إِبۡرَٰهِيمَ﴾⟪4:125⟫ أي: إذا فعل ذلك فقد قام مقام إبراهيم\nواستحق ما استحقه، ﴿وَٱتَّخَذَ ٱللَّهُ إِبۡرَٰهِيمَ خَلِيلٗا﴾⟪4:125⟫ أي: إنما\n⟦4:175⟧\nاصطفاه لما كان فيه لا لحاجة إليه فلله ما في السموات وما في الأرض،\nتنبيها على أنه غني عن عباده ومالك محيط بكل شيء، والواو في قوله: (ولله) واو الحال، وإن كان كثيرا تصوره أنه كلام مستأنف.\nإن قيل: كيف أعاد ذكر إبراهيم ولم يقل واتخذه؟\nقيل: لما كان ذلك كلاما مستأنفا، كان إعادة\nذكره أفحم، وأدل على موضع المدح، قال أبو القاسم البلخي: الخليل\nمن الخلة أي الفقر لا من الخلة، قال ومن قاسه بالحبيب فقد أخطأ، لأن الله\n⟦4:176⟧\nتعالى يجوز أن يحب عبده فالمحبة منه هي الثناء، ولا يجوز أن يخاله ما ليس بجنسه\n، وهذا منه تشبيه لحقيقة موضوع المحبة لا يصح عليه كما لا يصح عليه الخلة\n، فإن الخلة من تملك الود نفسه وخالطه، كقولهم: تمازح روحنا، ولهذا قال:\n⟦4:177⟧\nقد تخللت مسلك الروح مني ... وبذا سمي الخليل خليلا\nوالمحبة: البلوغ بالود إلى حبة القلب، من قولهم: حبيته أي أصبت حبة\nقلبه، نحو فأدته ورأسته، ومنكر أن يقال: حبيت الله، أو حبني الله، فإذا جاز في أبلغ اللفظ الاستعارة ففيما دونه أولى على معنى الثناء، كما ذكر أبو على أو علي معنى الاصطفاء، كما ذكر غيره."}, {"a": [127], "v": 4, "p": 177, "ev": 4, "ep": 181, "sid": 1669, "t": "قوله عز وجل: (ويستفتونك في النساء قل الله يفتيكم فيهن وما يتلى عليكم في الكتاب في يتامى النساء اللاتي لا تؤتونهن ما كتب لهن وترغبون أن تنكحوهن والمستضعفين من الولدان وأن تقوموا لليتامى بالقسط وما تفعلوا من خير فإن الله كان به عليما (127)\n⟦4:178⟧\nقوله: ﴿وَمَا يُتۡلَىٰ﴾⟪4:127⟫؟\nقيل: هو استئناف، على تقدير: ما يتلى عليكم بين لكم، وقيل: هو معطوف على الله أي: يفتيكم الله، ويفتيكم\nما يتلى عليكم، وقد تقدم في صدر الكتاب، أن فعلا واحدا يصح أن ينسب إلى فاعلين باعتبارات مختلفة.\nفالإشارة بذلك إلى قوله: ﴿وَإِنۡ خِفۡتُمۡ أَلَّا تُقۡسِطُواْ فِي ٱلۡيَتَٰمَىٰ﴾⟪4:3⟫، وإلى - قوله: ﴿يُوصِيكُمُ ٱللَّهُ فِيٓ أَوۡلَٰدِكُمۡۖ﴾⟪4:11⟫\n⟦4:179⟧\nوذلك أنه بين بالآيتين حكم المستفئ فيه، بسبب نزول الآية\nأن عيينة بن حصن أتى النبي - صلى الله عليه وسلم - فقال :\n(أخبرنا أنك تعطي الصبي المال وتعطي الابنة النصف والأخت النصف وإنما كنا نورث من يشهد القتال ويحوز الغنيمة، فقال عليه الصلاة والسلام: كذلك)، فأنزل الله تعالى الآية.\nقوله: ﴿وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ﴾⟪4:127⟫؟\nقيل: تقدير: في أن تنكحوهن،\nوقيل: عن أن تنكحوهن، قال أبو عبيدة: كلا التقديرين يصح\n⟦4:180⟧\nلأنك تقول: رغبت أن أصحبك، في معنيين، وكانوا يرغبون في الحسان من\nاليتامى فيتزوجوهن، وعن القباح فيعضلوهن ماكتب الله لهن؟\nقيل: المهر، وقيل: الإرث، الذي لها ومن أجله يرغبون فيها أو يعضلونها، استدل من الآية\n⟦4:181⟧\nعلى أنه يجوز التزوج اليتيمة الصغيرة، وأنه يجوز أن يزوجها غير الأب والجد.\nولا دلالة في الآية، لأنه قال: ﴿وَتَرۡغَبُونَ أَن تَنكِحُوهُنَّ﴾⟪4:127⟫ وذلك بلا\nاستقبال، ولم يذكر في الآية من نزوجها، ومن يزوجها، ولا قصد الآية إلى ذلك فبين حكمه فيها."}, {"a": [128], "v": 4, "p": 181, "ev": 4, "ep": 183, "sid": 1673, "t": "قوله تعالى: (وإن امرأة خافت من بعلها نشوزا أو إعراضا فلا جناح عليهما أن يصلحا بينهما صلحا والصلح خير وأحضرت الأنفس الشح وإن تحسنوا وتتقوا فإن الله كان بما تعملون خبيرا (128)\nالنشوز: أصله من النشز، وهو كالطموح، وأكثر ما يستعمل في بغض المرأة الرجل، والأظهر هاهنا أنه بغض الرجل للمرأة، ويحتمل أنها إن خافت أن ينشز عليها البعل، لإعادة غيرها عليها، فأباح تعالى أن يتصالحا على ترك بعض حقها، قال ابن عباس: هي أنها تكون قد طعنت في السن يرى الزوج استبدال غيرها بها، فتقول أرضي منك بغير نفقة، أو بغير قسمة،\nوقيل: نزلت في سودة، وكانت قد وهبت\n⟦4:182⟧\nيومها لعائشة.\nفإن قيل: لم قال: ﴿أَوۡ إِعۡرَاضٗا﴾⟪4:128⟫ والنشوز منطو على ذلك؟\nقيل: الإعراض أعم، فبين أن لا فرق من أن يكون النشوز، أو ما دون\nالنشوز، ثم قال ﴿وَٱلصُّلۡحُ خَيۡرٞۗ﴾⟪4:128⟫؟\nقيل: خير من النشوز، وقيل: خير من\nالفرقة، والأجود أن يكون ذلك عاما فيهما، وفي غيرهما، فإن الناس مدعوون إلى التآلف، والتحاب، ولهذا قال عليه الصلاة والسلام:\n\" لا تقاطعوا ولا تدابروا وكونوا عباد الله إخوانا \"،\nوكل موضع يمكن فيه الصلح أحرى بالصلاح على ما يقتضيه العقل والشرع، فالصلح خير، فصار ذلك اعتراضا عاما، تنبيها أن هذا الموضع منه فهو اذن خير، وكذا قوله\n⟦4:183⟧\n﴿وَأُحۡضِرَتِ ٱلۡأَنفُسُ ٱلشُّحَّۚ﴾⟪4:128⟫ اعتراضا، تنبيها على ما في ذات الإنسان، والشح أبلغ من البخل إذ هو غريزة.\nفإن قيل: فلم ذم إذا الإنسان عليه؟\nقيل: ذم الإنسان إنما هو باتباعه بأكثر مما يجب، كما يذم باتباع الشهوة ووجوده في الإنسان محمود لوجود الشهوة، واتباعه هو المكروه،\nولهذا قال عليه الصلاة والسلام (ثلاث مهلكات شح مطاع)\nفذم طاعة الشح لا ذاته ثم حرض على الإحسان والتقوى وضمن أنه يجازي بها، بقوله: ﴿فَإِنَّ ٱللَّهَ كَانَ بِمَا تَعۡمَلُونَ خَبِيرٗا﴾⟪4:128⟫."}, {"a": [129], "v": 4, "p": 183, "ev": 4, "ep": 185, "sid": 1675, "t": "قوله تعالى: (ولن تستطيعوا أن تعدلوا بين النساء ولو حرصتم فلا تميلوا كل الميل فتذروها كالمعلقة وإن تصلحوا وتتقوا فإن الله كان غفورا رحيما (129)\n⟦4:184⟧\nنبه تعالى على قصور الإنسان عن تحري العدالة بين نسائه، وأن يحرص على\nتحريها سيما في الحب، ونهى عن كل الميل عن واحدة فتكون معلقة لا زوجا\nمطلقة ولا ذات بعل، لا بعضه، نبه الله تعالى على صعوبة تحري الحق، وأن\nالإنسان إذا لم يستطع العدل بينه وبين امرأته مع أن حقها معلوم، فكيف يستطيع أن يعدل بينه وبين رب العزة ونعمه لا تحصى، وحقوقه لا تستقصى، كما قال تعالى: ﴿وَإِن تَعُدُّواْ نِعۡمَتَ ٱللَّهِ لَا تُحۡصُوهَآۗ﴾⟪14:34⟫، ولهذا قال عليه الصلاة والسلام: (استقيموا ولن تحصوا)،\nثم قال: ﴿وَإِن تُصۡلِحُواْ وَتَتَّقُواْ﴾⟪4:129⟫ أي: إن تحريتم الصلاح، واستجملتم التقوى بقدر وسعكم، فهو ما كان منكم.\nفإن قيل: إذا كان الله لا يكلف إلا الوسع، وقد حكم أنكم لا تستطيعون\n⟦4:185⟧\nأن تعدلوا، فلا ذنب فيما لا يستطاع، فكيف يغفر ذلك والغفران لا يكون إلا لذنب؟\nقيل: الإنسان وإن كان لا يستطيع أن يعدل بين نسائه، فإنه يمكنه أن\nيحترز من ذلك بأن لا يتزوج بعدة منهن، وكل ما دخل فيما لا يستطيعه فهو\nمأخوذ بدخوله فيه، كمن شرب فسكر، ثم جنى جناية، فإنه مأخوذ بجنايته، لما كان هو سبب سكره، وروى أن النبي - صلى الله عليه وسلم - كان يقول (اللهم إني أعدل فيما أعدل واستغفرك فيما لا أملك)،\nوكان يطوف بين نسائه ليقسم بينهن، ثم استأذهن أن تمرضه عائشة."}, {"a": [130], "v": 4, "p": 186, "ev": 4, "ep": 186, "sid": 1678, "t": "قوله تعالى: (وإن يتفرقا يغن الله كلا من سعته وكان الله واسعا حكيما (130)\nهوكقوله: ﴿فَإِمۡسَاكُۢ بِمَعۡرُوفٍ أَوۡ تَسۡرِيحُۢ بِإِحۡسَٰنٖۗ﴾⟪2:229⟫ وقولهم: إن لم يكن\nوفاق فطلاق، كما أن لهما أن يصالحا بالوفاق، وبين أنه وإن خلقهم، خلقهم يضطر كل واحد منهما إلى صاحبه، فقد أغنى كل واحد منهما عن الآخر يبدل له آخر، فهذا معنى الغنى، وفيه أيضا إشارة إلى الغنى المالي،\nوقد روي عن الحسن بن علي أنه كان طلق زوجته، فقيل: له في ذلك، فقال: إني رأيت الله تعالى علق على الأمرين غنى، فقال تعالى: ﴿وَأَنكِحُواْ ٱلۡأَيَٰمَىٰ مِنكُمۡ﴾⟪24:32⟫ الآية، وقال: ﴿وَإِن يَتَفَرَّقَا يُغۡنِ ٱللَّهُ كُلّٗا مِّن سَعَتِهِۦۚ﴾⟪4:130⟫\nوالواسع: عام في الغنى، والقدرة، والعلم، وعقبه بالحكم، منبها أن السعة ما لم يكن معها الحكمة، والعلم، كان إلى الفساد أقرب منها إلى الصلاح."}, {"a": [131, 132], "v": 4, "p": 187, "ev": 4, "ep": 187, "sid": 1679, "t": "قوله تعالى: (ولله ما في السماوات وما في الأرض ولقد وصينا الذين أوتوا الكتاب من قبلكم وإياكم أن اتقوا الله وإن تكفروا فإن لله ما في السماوات وما في الأرض وكان الله غنيا حميدا (131)\nلما قال ﴿يُغۡنِ ٱللَّهُ كُلّٗا مِّن سَعَتِهِۦۚ﴾⟪4:130⟫، نبه على قدرته على ذلك بقوله تعالى: ﴿وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ﴾⟪4:131⟫، وسلاه عما يفوته من أغراض الدنيا، بالاعتماد عليه تعالى، وأكد ما قدمه من الأمر بالإصلاح بقوله تعالى: ﴿وَلَقَدۡ وَصَّيۡنَا ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ﴾⟪4:131⟫ تنبها أنه لم يزل يوصي بفعل الخير، وبين أن ذلك لرحمته لا لحاجته فهو غني وقوله تعالى: ﴿وَكَفَىٰ بِٱللَّهِ وَكِيلًا﴾⟪4:132⟫،\nراجع إلى قوله: ﴿يُغۡنِ ٱللَّهُ كُلّٗا﴾⟪4:130⟫ أي: توكلت بكفايتكم، وكفى به وكيلا، وأعاد قوله: ﴿وَلِلَّهِ مَا فِي ٱلسَّمَٰوَٰتِ وَمَا فِي ٱلۡأَرۡضِۗ﴾⟪4:131⟫ ثلاث مرات لثلاثة معان:\nالأول: تسلية للإنسان عما فاته، والثاني: أن وصيته لرحمته لا لحاجته وأنهم إن كفروا به لا يضروه شيئا، والثالث: دلالة على كونه غنيا."}, {"a": [133], "v": 4, "p": 187, "ev": 4, "ep": 188, "sid": 1679, "t": "قوله عز وجل: (إن يشأ يذهبكم أيها الناس ويأت بآخرين وكان الله على ذلك قديرا (133)\nأي: هو غني عن خلقه، ومع غناه قادر على\nإفناء قوم والإتيان بآخرين، كما قال: ﴿وَإِن تَتَوَلَّوۡاْ يَسۡتَبۡدِلۡ قَوۡمًا غَيۡرَكُمۡ﴾⟪47:38⟫\n⟦4:188⟧\nوكما قال: ﴿وَيَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا يَشَآءُ﴾⟪6:133⟫\nقال: (ألم تر أن الله خلق السماوات والأرض بالحق إن يشأ يذهبكم ويأت بخلق جديد (19)،\nويقال لما نزلت الآية ضرب يده عليه الصلاة والسلام على ظهر سلمان\nوقال: (فمن قوم هذا).\nوقوله: (يذهبكم) على هذا ليس يشير إلى الأعيان فقط، بل إلى الأنواع الذين هم العرب والعجم."}, {"a": [134], "v": 4, "p": 188, "ev": 4, "ep": 192, "sid": 1680, "t": "قوله تعالى: (من كان يريد ثواب الدنيا فعند الله ثواب الدنيا والآخرة وكان الله سميعا بصيرا (134)\nلما بين أن\n⟦4:189⟧\nله ما في السموات وما في الأرض.\nبين أنه يعطي منهما ما يشاء من يشاء فثواب\nالدنيا يرجع إلى ملك الآخرة، وهو الغنيمة وغيرها، من الأغراض الدنيوية\nوثواب الآخرة يرجع إلى ملك السموات وهو الثواب الأخروي، ونبه أن كليهما منه كقوله: ﴿مَن كَانَ يُرِيدُ ٱلۡحَيَوٰةَ ٱلدُّنۡيَا وَزِينَتَهَا نُوَفِّ إِلَيۡهِمۡ أَعۡمَٰلَهُمۡ﴾⟪11:15⟫ الآية، وكقوله: ﴿وَمَن كَانَ يُرِيدُ حَرۡثَ ٱلدُّنۡيَا نُؤۡتِهِۦ مِنۡهَا﴾⟪42:20⟫ الآية،\nوبين بقوله: ﴿وَكَانَ ٱللَّهُ سَمِيعَۢا بَصِيرٗا﴾⟪4:134⟫ أنه عارف بالأغراض، والمقاصد، فهو يجازي كلا بحسب مقصده فالأعمال بالنيات،\nونبه أيضا أنه يؤتي كل واحد من أغراض الدنيا ما يراه أصلح له، كما قال: ﴿مَّن كَانَ يُرِيدُ ٱلۡعَاجِلَةَ عَجَّلۡنَا لَهُۥ فِيهَا مَا نَشَآءُ لِمَن نُّرِيدُ﴾⟪17:18⟫\n⟦4:190⟧\nوفي قوله: ﴿فَضۡلُ ٱللَّهِ﴾ ثواب الدنيا والآخرة تبكيت\nللإنسان حيث اقتصر على أدق السؤالين، مع كون المسؤول مالكا له ولا أشرف منه، وحث على أن يطلب منه ما هو أعلى، وأفضل من مطلوبه، وأن من طلب خسيسا مع أنه يمكنه أن يطلب نفيسا فهو دنيء الهمة. \\قوله عز وجل: (يا أيها الذين آمنوا كونوا قوامين بالقسط شهداء لله ولو على أنفسكم أو الوالدين والأقربين إن يكن غنيا أو فقيرا فالله أولى بهما فلا تتبعوا الهوى أن تعدلوا وإن تلووا أو تعرضوا فإن الله كان بما تعملون خبيرا (135)\nأمر تعالى كل إنسان مراعاة العدالة،\nونبه بلفظ (قوامين) على أن ذلك لا يكفي مرة ومرتين ،\nبل يجب أن يكون على الدوام، فالأمور الدينية لا اعتبار لها ما لم تكن على الدوام، ومن عدل مرة ومرتين لا يكون في الحقيقة عادلا وبين أن العدالة التامة أن يكون حكم الإنسان على نفسه، وذويه، كحكمه على الأجانب، وإلى ذلك أشار النبي - صلى الله عليه وسلم - بقوله: (أن تريد لأخيك ما تريد لنفسك)، ونبه على أنه لا يجب أن ينتفع من إيجاب\n⟦4:191⟧\nالحقوق محاباة لفقر من عليه الحق، أو ميلا لغئ غني فالله أرأف بعباده، وقوله:\n﴿وَلَوۡ عَلَىٰٓ أَنفُسِكُمۡ﴾⟪4:135⟫ حث على إقامة الشهادة على نفسه بالإقرار، وعلى\nدونه، ونحوه قوله: ﴿وَإِذَا قُلۡتُمۡ فَٱعۡدِلُواْ وَلَوۡ كَانَ ذَا قُرۡبَىٰۖ وَبِعَهۡدِ ٱللَّهِ أَوۡفُواْۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَذَكَّرُونَ﴾⟪6:152⟫ ونص بعض الناس أن ذلك شهادة لهم، وقال: في صدر الإسلام كانت تقبل شهادة الإنسان لأبيه، ثم نسخ، وليست الآية تقضي إلا إقامة الشهادة عليهم لا لهم وذلك مقبول بكل حال، ونهي عن إلزام الحق والتزامه اتباعا للهو ى، وتقدير: (أن تعدلوا) كراهية أن تعدلو، وقيل:\n⟦4:192⟧\nلا تتبعوا الهوى لتعدلوا، أي: لتكونوا في اتباعكم عدولا، تنبيها أن اتباع الهوى وتحري العدالة متنافيان لا يجتمعان،"}, {"a": [135], "v": 4, "p": 192, "ev": 4, "ep": 193, "sid": 1684, "t": "قوله -: ﴿وَإِن تَلۡوُۥٓاْ أَوۡ﴾⟪4:135⟫ إشارة إلى التكبر عن قول الحق، نحو قوله: ﴿وَإِذَا قِيلَ لَهُمۡ تَعَالَوۡاْ يَسۡتَغۡفِرۡ لَكُمۡ رَسُولُ ٱللَّهِ لَوَّوۡاْ رُءُوسَهُمۡ﴾⟪63:5⟫ الآية، وإنما قال بهما وأنت تقول رأيت زيدا أو عمرا فأكرمته، ولا تقول فأكرمتهما، فإن الإكرام يتعلق بأحدهما، والآية تتعلق بالناس كلهم غنيهم وفقيرهم، وجعلهم شهداء لله تعظيما لمراعاة العدالة وأنه بالحفظ لها يصير من شهداء الله، وانتصابها على الحال لقوله:\n⟦4:193⟧\n(قوامين) أو صفة لها أو يكون قوامين حالا، وشهداء خبر كان، ومن\nقرأ (تلوه) فمن ولي يلي، كأنه قال: (وإن تلووا أو تعرضوا فإن الله كان بما تعملون خبيرا) ومن قرأ (تلووا) فقد قيل: جعله من اللي، أي: المطل، وفي ذلك مخاطبة لمن عليه الحق في ترك المطل، وللحاكم إذا تقدم\nإليه الخصمان أن لا يدفع الطالب عنه حقه، والشاهدان لا يمتنع بالشهادة لهم"}, {"a": [136], "v": 4, "p": 194, "ev": 4, "ep": 196, "sid": 1686, "t": "قوله عز وجل: (يا أيها الذين آمنوا آمنوا بالله ورسوله والكتاب الذي نزل على رسوله والكتاب الذي أنزل من قبل ومن يكفر بالله وملائكته وكتبه ورسله واليوم الآخر فقد ضل ضلالا بعيدا (136)\nقيل: معناه يا أيها الذين آمنوا بمحمد أديموا الإيمان، وقيل: معناه يا أيها الذين آمنوا بالأنبياء، قبل محمد آمنوا بمحمد،\nوقال الزجاج: خاطب بذلك المنافقين الذين أظهروا الإيمان، وتقديره: على\nما قال أن الإيمان ضربان: ضرب: هو يحكم به في الظاهر، وهو الإتيان\nبالشهادتين والتزام أحكام الشريعة، وهو الذي يحصن دم الإنسان وماله إلا بحقه، وضرب: هو التخصص بحقائقه التي اقتضاها، قوله:\n⟦4:195⟧\n﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ ءَامَنُواْ بِٱللَّهِ وَرَسُولِهِۦ ثُمَّ لَمۡ يَرۡتَابُواْ﴾⟪49:15⟫،\nوقوله: ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ ٱلَّذِينَ إِذَا ذُكِرَ ٱللَّهُ وَجِلَتۡ قُلُوبُهُمۡ﴾⟪8:2⟫، وقد\nبينت في مكارم الشريعة أن الإيمان كما قال عليه الصلاة والسلام: (اثنان\nوسجون درجة)، وبينت القانون الذي اقتضى ذلك، وأن تلك المراتب بعضها على بعض، فالإنسان إلى أن يصل في آخر درجة منها مأمور بالترقي إلى ما فوق منزلته، فالآية خطاب يتوجه على كافة المؤمنين أن يترقوا في تلك الدرجات، وقد ذكر تعالى في هذه الآية ما هو الإيمان الاعتقادي، وذلك الخمسة، وذلك هو الإيمان بالله وبالملائكة والكتاب والرسول واليوم الآخر، وهي المذكورات في خبر جبريل عليه الصلاة والسلام (حيث أتى النبي عليه الصلاة والسلام في صورة أعرابي فقال له: ما الإيمان؟) وذكر أن الكفر بهذا هو الضلال البعيد، فنبه أن\n⟦4:196⟧\nالانسلاخ من الهداية والضلال الذي قلما يرجي عود صاحبه، وقد ذكرت كيفية الضلال عن - الطريق في مكارم الشريعة."}, {"a": [137], "v": 4, "p": 196, "ev": 4, "ep": 198, "sid": 1688, "t": "قوله: (إن الذين آمنوا ثم كفروا ثم آمنوا ثم كفروا ثم ازدادوا كفرا لم يكن الله ليغفر لهم ولا ليهديهم سبيلا (137)\nقال قتادة: يعني أهل الكتابيين اليهود، آمنوا بموسى ثم كفروا بمن عداه، والنصارى آمنوا بعيسى وكفروا بمن عداه، ثم ازدادوا كلهم كفرا بمحمد، وقيل: آمنوا. بموسى ثم كفروا به لأنهم لم يؤمنوا\nبعده بعده فهم في حكم من لم يؤمن، وقال مجاهد: هو في المنافقين المذكورين\nفي قوله: (وإذا لقوا الذين آمنوا قالوا آمنا وإذا خلوا إلى شياطينهم قالوا إنا معكم إنما نحن مستهزئون (14)\n⟦4:197⟧\nوقيل: هي في الذين قال فيهم: (وقالت طائفة من أهل الكتاب آمنوا بالذي أنزل على الذين آمنوا وجه النهار واكفروا آخره لعلهم يرجعون (72)،\nولم يرد أنهم آمنوا مرتين وكفروا مرتين وإنما ذلك إشارة إلى أحوال كثيرة، كقولك: فلان فعل ثم امتنع إلى هذا كان دأبه،\nوقيل: كما أن الإنسان يندرج إلى غاية الفضائل ثلاث درجات، وهو أن\nيحصل في أولها، ثم في أوسطها، ثم في منتهاها، كذلك يتضلع في الرذائل ثلاث درجات، ولذلك جعل الله له ثلاث عقوبات الرين والغشاوة والطبع، ومن\n⟦4:198⟧\nترك الإيمان مرة بعد مرة، ثم ازداد تماديا في الغي، فقد صار من الذين وصفهم بقوله: ﴿أُوْلَٰٓئِكَ ٱلَّذِينَ لَعَنَهُمُ ٱللَّهُ فَأَصَمَّهُمۡ وَأَعۡمَىٰٓ أَبۡصَٰرَهُمۡ﴾⟪47:23⟫، ثم قال: ﴿أَفَلَا يَتَدَبَّرُونَ ٱلۡقُرۡءَانَ أَمۡ عَلَىٰ قُلُوبٍ أَقۡفَالُهَآ﴾⟪47:24⟫، فبين تعالى أن من انتهى في الغي إلى هذا المنزل فقد صار بحيث لا يتوب، وإذا لم يتب لم يغفر له ولا ليهديه إذ هو لا يهتدي لكونه مطبوعا على قلبه لما ارتكبه،\nوقال بعض الفقهاء: إن المرتد تقبل توبته سار\nبالكفر أولم يسر، لأنه جعلهم مؤمنين بعد دخولهم في الكفر."}];
